INSERT INTO `wp_options` VALUES (1598,'_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"WordPress.org blog: WordPress 7.2 Beta 1 is Ready for Download and Testing\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21813\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:17138:\"<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 1 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta1.zip\">Beta 1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-beta1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/?site-slug=kind-classic-mountain&amp;networking=no&amp;php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.2 Beta 1 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Editing Experience</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Responsive Design Controls</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Building on the responsive design improvements introduced in WordPress 7.1, WordPress 7.2 expands viewport-specific styling to additional design tools and blocks. Creators gain more granular control over how layouts and visual settings adapt across screen sizes, including responsive Gallery settings for columns, image cropping, and aspect ratios.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/80388\">GitHub #80388</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82003\">#82003</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Improved Global Styles and Design Tools</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21825\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 makes site-wide styling easier to manage with a new <em>Customized</em> filter for finding blocks with modified styles and inherited Global Styles values displayed directly in block inspector controls. Expanded design tools and support for styling form elements provide additional flexibility when creating a consistent visual identity across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/82520\">GitHub #82520</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/76525\">#76525</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/34198\">#34198</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84657\">#84657</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Text Shadow Support</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces new text shadow controls, giving creators more ways to add depth and emphasis to their content. Text shadows can be customized through block settings and defined as presets in <code>theme.json</code>, making it easier to maintain consistent typography across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/73320\">GitHub #73320</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79584\">GitHub #79584</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">Trac #65869</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Easier Navigation Management</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Improvements to the Site Editor make managing navigation links more intuitive. Creators can add, organize, and edit navigation items directly from the editor sidebar, making it easier to maintain site menus without interrupting their editing workflow.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/77069\">GitHub #77069</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Better Collaboration with Notes</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21820\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces Emoji reactions on notes and a new toolbar icon that makes Notes easier to access and manage. Notes move to the editor canvas, bringing conversations directly into the margin. Users can now keep Notes and the block settings sidebar open simultaneously, making it easier to review feedback while editing content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A new minimized Notes mode reduces visual clutter, while improvements to positioning and display create a smoother, more consistent collaboration experience.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/79970\">GitHub #79970</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83786\">GitHub #83786</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/80015\">GitHub #80015</a>, <a href=\"https://core.trac.wordpress.org/ticket/64638\">Trac #64638</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster, More Efficient Media Uploads</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands client-side media processing to the Media Library, allowing images to be resized, compressed, and converted directly in the browser before being uploaded. This can improve upload performance, reduce server resource usage, and provide better support for modern image formats, particularly on hosting environments with limited image-processing capabilities.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65661\">Trac #65661</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/12585\">GitHub #12585</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">New “On This Day” Dashboard Widget</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a new <strong>On This Day</strong> dashboard widget that helps users rediscover content published on the same date in previous years. By highlighting posts from the site&#8217;s history, the widget makes it easier to revisit past content, celebrate milestones, and find opportunities to refresh or reshare older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65116\">Trac #65116</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Block Editor Usability Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 includes a collection of smaller improvements aimed at reducing friction in everyday editing. These changes include clearer error messages, more helpful feedback when something goes wrong, and refinements to common editor interactions, making the editing experience more predictable and approachable.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21821\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/81453\">GitHub #81453</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82496\">#82496</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84656\">#84656</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84649\">#84649</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">A More Consistent WordPress Admin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 continues modernizing the administration experience by replacing legacy Dashicons in the admin bar and sidebar with icons from the WordPress icon library. The updated icons bring greater visual consistency between the traditional WordPress dashboard and newer editing interfaces.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/wordpress-develop/pull/12270\">GitHub #12270</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">An Updated Block Settings Experience</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21822\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A new DataForm-powered inspector introduces a refreshed approach to managing block settings in the editor. Built on the DataForm component system, this work aims to provide more consistent controls and a more extensible foundation for future block editing improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg\">GitHub Gutenberg</a> · <a href=\"https://make.wordpress.org/core/2026/09/17/call-for-testing-dataform-editor-inspector/\">Call for Testing</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster WordPress Administration</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 improves admin performance by modernizing how scripts and stylesheets are loaded. Instead of combining assets into large files, WordPress now loads them individually for better browser caching. A new prefetching mechanism also anticipates which admin screen users are likely to visit next, loading its resources in advance to make navigation between the dashboard, post lists, and editor faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/57548\">Trac #57548</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">For Developers</h2>\n\n\n\n<h3 class=\"wp-block-heading\">New Secrets API</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a <strong>Secrets API</strong>, providing developers with a standardized, secure way to store sensitive credentials such as API keys and authentication tokens. The API supports encryption at rest, credential rotation, and customizable storage providers, helping plugins and integrations manage sensitive information more securely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://core.trac.wordpress.org/ticket/66187\">Learn more (Trac #66187)</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Random Content Redirects</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 adds support for random content redirects, allowing visitors to discover a randomly selected post through a dedicated URL. This provides a simple way to encourage content exploration and help readers rediscover older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/64498\">Trac #64498</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">More Powerful APIs for Developers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands the <strong>Abilities API</strong> with new capabilities for accessing and querying WordPress data, providing a more consistent foundation for integrations, automation, and AI-powered tools. (<a href=\"https://core.trac.wordpress.org/ticket/66268\">Trac #66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/64605\">#64605</a>, <a href=\"https://core.trac.wordpress.org/ticket/64657\">#64657</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Enhancements to the <strong>Interactivity API</strong> introduce new ways to render trusted HTML and manage reactive navigation, giving developers more flexibility when building dynamic, interactive blocks. (<a href=\"https://core.trac.wordpress.org/ticket/66246\">Trac #66246</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83092\">Gutenberg PR #83092</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional improvements to the <strong>HTML API</strong>, block supports, and responsive design tools provide more reliable markup processing and greater control over how custom blocks are styled and displayed across devices. (<a href=\"https://core.trac.wordpress.org/ticket/65824\">Trac #65824</a>, <a href=\"https://core.trac.wordpress.org/ticket/66150\">#66150</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">#65869</a>)</p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the<a href=\"https://make.wordpress.org/test/\"> testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 will include new features that were previously only available in the Gutenberg plugin. Learn more about Gutenberg updates since WordPress 7.1 in the <a href=\"https://make.wordpress.org/core/tag/gutenberg-new/\">What’s New in Gutenberg</a> posts for versions <a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">23.7</a>, <a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">23.8</a>, <a href=\"https://make.wordpress.org/core/2026/09/02/whats-new-in-gutenberg-23-9-2-september/\">23.9</a>, <a href=\"https://make.wordpress.org/core/2026/09/16/whats-new-in-gutenberg-24-0-16-september/\">24.0</a>, <a href=\"https://make.wordpress.org/core/2026/09/30/whats-new-in-gutenberg-24-1-30-september/\">24.1</a>, <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\">24.2</a>, and 24.3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What’s new in WordPress 7.2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">With so much in progress for WordPress 7.2 Beta 1, this is still only the beginning; expect continued refinement with each Beta and RC release ahead of the final release on <strong>December 8, 2026</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Just for you: a Beta 1 haiku:</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Ipsum takes the stage<br />Secrets bloom, designs take shape<br />New blocks come alive</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to </em><a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/annezazu/\"><span class=\"mentions-prefix\">@</span>annezazu</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/adamsilverstein/\"><span class=\"mentions-prefix\">@</span>adamsilverstein</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/westonruter/\"><span class=\"mentions-prefix\">@</span>westonruter</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/markoserb/\"><span class=\"mentions-prefix\">@</span>markoserb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/im3dabasia1/\"><span class=\"mentions-prefix\">@</span>im3dabasia1</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/jorbin/\"><span class=\"mentions-prefix\">@</span>jorbin</a>, and <a class=\"mention\" href=\"https://profiles.wordpress.org/noruzzaman/\"><span class=\"mentions-prefix\">@</span>noruzzaman</a><em> for proofreading and review.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 16:02:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"Open Channels FM: Community Without the Noise, Revisited\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564390\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"https://openchannels.fm/community-without-the-noise-revisited/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"A commentary on building meaningful online communities that prioritize value and listening over constant activity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 13:46:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"OpenStation Blog: OpenStation: turn wp-admin into a desktop, and try it in 30 seconds\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1495\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:102:\"https://openstation.blog/2026/10/20/openstation-turn-wp-admin-into-a-desktop-and-try-it-in-30-seconds/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2722:\"<p class=\"wp-block-paragraph\">OpenStation is a free WordPress plugin that turns wp-admin into a desktop. Every admin screen opens in its own window that you can move, resize and keep open next to the others. You can try it in your browser right now, with nothing to install.</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Can&#8217;t see the video? <a href=\"https://www.youtube.com/watch?v=g5MLB3WMlCc\">Watch it on YouTube</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why we built it</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Most of us spend the day jumping between screens in wp-admin. You open a post, go back to the list, check the media library, then go back again. With OpenStation, those screens stay open side by side, so you don&#8217;t lose your place.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What you get</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A window for every admin page: posts, media, settings, plugins</li>\n\n\n\n<li>A dock with your whole admin menu, including your other plugins</li>\n\n\n\n<li>Several desktops, for example one for writing and one for site settings</li>\n\n\n\n<li>Wallpapers, widgets and accent colors</li>\n\n\n\n<li>Cmd+K to jump anywhere fast</li>\n\n\n\n<li>Your windows are still open when you come back</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Try it in your browser</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Go to the <a href=\"https://wordpress.org/plugins/desktop-mode/\">OpenStation page on WordPress.org</a> and click <strong>Live Preview</strong>. It runs a full WordPress site with OpenStation in your browser tab, so you can&#8217;t break anything.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Install it on your site</h2>\n\n\n\n<ol class=\"wp-block-list\">\n<li>In your admin, go to Plugins → Add New and search for &#8220;OpenStation&#8221;</li>\n\n\n\n<li>Click Install Now, then Activate</li>\n\n\n\n<li>Click the desktop icon in the top-right corner of the admin bar</li>\n</ol>\n\n\n\n<h2 class=\"wp-block-heading\">It&#8217;s safe to try</h2>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation is opt-in for each user, so the rest of your team keeps the normal admin. Click the same icon to go back to the classic view. If you deactivate the plugin, wp-admin goes back to exactly how it was. It doesn&#8217;t change WordPress core.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Tell us what you think</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Have a question? Ask in the <a href=\"https://wordpress.org/support/plugin/desktop-mode/\">support forum</a>. Found a bug or have an idea? <a href=\"https://github.com/WordPress/openstation/issues\">Open an issue on GitHub</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 13:44:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"Open Channels FM: More Code, More Problems? What AI-Generated Software Means for Us\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563871\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://openchannels.fm/more-code-more-problems-what-ai-generated-software-means-for-us/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:327:\"AI tools have simplified app creation, enabling rapid prototyping. However, the challenge now lies in discerning which ideas are genuinely valuable to users. As anyone can create apps quickly, the focus should shift from mere production to understanding user needs and ensuring the apps solve real problems to avoid mediocrity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 10:01:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:41:\"Donncha: Travel Steps is a travel journal\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89593168\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://odd.blog/2026/10/19/travel-steps-is-a-travel-journal/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:10011:\"<p class=\"wp-block-paragraph\">I made a WordPress plugin for my holidays. It&#8217;s called Travel Steps, and it turns a trip into a page with a map down one side and the story of each day down the other.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593171 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/01-trip-header.avif\" width=\"2000\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Every photo I take ends up in <a href=\"https://immich.app\">Immich</a>, on my own server. My phone sends where I&#8217;ve been to <a href=\"https://dawarich.app\">Dawarich</a>, on the same server. So after a trip I have all the photos and the whole route, sitting in two apps on my private server. The travel apps that make nice trip pages want your photos and your location on their servers. I&#8217;d rather keep them on mine.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How it works</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You make a trip, give it a first and last day, and press Sync. Travel Steps asks Dawarich for your location over those days, and Immich for the photos you took. You can pick one Immich album instead. If you don&#8217;t use Immich at all, upload the photos to the trip. It will detect the start and end dates from the uploaded photos, or an Immich album too.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593182 not-transparent\" height=\"1480\" src=\"https://odd.blog/files/2026/10/08-sync-and-steps.avif\" width=\"1520\" /><figcaption class=\"wp-element-caption\">One sync, and a step for each day.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Sync makes a draft post for every day that has favourite photos. Each one is a &#8220;step&#8221;. It splits the day into places too. A new place starts when a favourite is more than 2 km from the last one and in a different town. Each place gets a heading and a block of photos, so all that&#8217;s left is the writing.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593175 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/09-block-editor.avif\" width=\"2000\" /><figcaption class=\"wp-element-caption\">Each day is a post you write in the block editor. The photos under each heading come straight from Immich.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Place names come from <a href=\"https://www.geonames.org\">GeoNames</a> data that ships with the plugin, so naming a town doesn&#8217;t send your location anywhere. Immich only names a place from a photo&#8217;s own GPS. A photo from a camera without GPS gets placed from your Dawarich history instead, and named the same way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Publish the days you want people to see. Drafts stay private, and so do their photos.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593174 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/02-map-timeline.avif\" width=\"2000\" /><figcaption class=\"wp-element-caption\">The map follows you as you scroll. Get to day 3 and day 3&#8217;s markers light up.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The distance at the top follows the whole route, flights included. GPS glitches that put you in the Atlantic for a second are dropped. Anything you&#8217;d have needed to travel faster than 1,080 km/h to reach counts as a glitch. Sorry, Concorde.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Your photos stay at home</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Visitors never talk to Immich. WordPress fetches each photo, caches it and serves it itself, so Immich and the original files stay private. It caches a trip&#8217;s photos in the background after a sync. The trip keeps working when Immich is down. A daily sweep deletes cached photos older than a number of days you choose, whether a trip still uses them or not, and they&#8217;re fetched again the next time someone looks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Photos you upload to a trip keep their GPS in the original, but it&#8217;s stripped from every copy WordPress makes, and only those copies are ever sent. A trip can have a password, and you can let some logged-in people skip it.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Pin, hide, cover</h2>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593176 not-transparent\" height=\"1060\" src=\"https://odd.blog/files/2026/10/03-photo-tools.avif\" width=\"1300\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Hover over a photo to pin it (always show it), hide it, or make it the trip&#8217;s cover. The rest of the day&#8217;s photos sit behind a &#8220;Show more photos&#8221; link.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On phones, those buttons show up after you press Edit photos as illustrated by the images below.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593177 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/04-phone-trip.avif\" width=\"924\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593178 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/05-phone-edit-photos.avif\" width=\"924\" /></figure>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Tap a photo and it opens full screen. On a phone you swipe from one photo to the next, edge to edge. On a desktop there are arrows, and the arrow keys work too.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593185 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/07-phone-lightbox.avif\" width=\"924\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593179 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/06-phone-lightbox-swipe.avif\" width=\"924\" /></figure>\n</div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Try it</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Here&#8217;s a <a href=\"https://playground.wordpress.net/?blueprint-url=https://raw.githubusercontent.com/donnchawp/travel-steps/master/demo/blueprint.json\">demo in WordPress Playground</a>. It&#8217;s a week in the west of Ireland, running in your browser that installs nothing. Stand-in Immich and Dawarich servers feed the real sync code with photos from Unsplash. You&#8217;re logged in as an admin, so press Sync, pin and hide photos, and edit the days in the block editor. It all disappears when you close the tab.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The code is <a href=\"https://github.com/donnchawp/travel-steps\">on GitHub</a>. To install it, download <code>travel-steps.zip</code> from the <a href=\"https://github.com/donnchawp/travel-steps/releases/latest\">latest release</a> and upload it under Plugins → Add New. It needs WordPress 6.7 and PHP 8.0. Immich and Dawarich are both optional. It has been submitted to WordPress.org but if you read this blog, you&#8217;ll know how to install a plugin from a zip file!</p>\n\n\n\n<h2 class=\"wp-block-heading\">WpApp</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Travel Steps is built on <a href=\"https://github.com/akirk/wp-app\">WpApp</a>, Alex Kirk&#8217;s framework for building apps on top of WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A plugin usually adds screens to wp-admin, or puts its pages inside your theme and hopes the CSS gets along. A WpApp app gets its own URLs instead (<code>/travel-steps/</code> here), and its pages are plain HTML with no theme in the way. WordPress still does the boring work: users and logins, roles, the block editor, the REST API, cron and the database. WpApp adds the bits in between:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>URL routing, using WordPress rewrite rules,</li>\n\n\n\n<li>pages that don&#8217;t load your theme,</li>\n\n\n\n<li>the admin bar on every page, with the app&#8217;s own icon (the green map at the top of my screenshots),</li>\n\n\n\n<li>access control using WordPress capabilities.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can start one with <code>composer create-project akirk/create-wp-app my-app</code>. Alex has a <a href=\"https://wpapps.kirk.at/\">showcase of apps built with it</a>, including a cookbook and a family wiki.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Built with Claude Code</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I wrote Travel Steps with <a href=\"https://claude.ai/code\">Claude Code</a>. The first commit was on 11 October, and there are many more now. Most of the work went round the same loop. I file an issue, Claude fixes it test-first on a branch and opens a pull request, and other agents review it. I deploy it to my own server and try it. The tests run in WordPress Playground too, the same as the demo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you run Immich, give it a whirl. Bug reports welcome on GitHub <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"has-small-font-size wp-block-paragraph\">Demo photos from <a href=\"https://unsplash.com\">Unsplash</a>: Cliffs of Moher by <a href=\"https://unsplash.com/photos/Zf9bvJ6182k\">Jarek Skowron</a>, Temple Bar by <a href=\"https://unsplash.com/photos/-ABmxr3Yo4Y\">Sarah</a>, Galway by Daniel Zbroja and Anna Hunko, Kilronan by Jonathan Borba. Map © <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors.</p>\n\n#TravelSteps #WordPress #WordPressplugin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 14:15:48 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"WordCamp Central: WordPress Campus Connect Ahmad Education, Dhaka 2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16498954\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"https://central.wordcamp.org/news/2026/10/wordpress-campus-connect-ahmad-education-dhaka-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4340:\"<div class=\"wp-block-columns has-black-background-color has-text-color has-background has-link-color has-small-font-size wp-elements-6 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\" style=\"color: #ffffff;\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading has-white-color has-text-color has-link-color wp-elements-7\">The Truly Meaning moment in this event</h3>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-8 wp-block-paragraph\">Campus Connect Event Successfully Completed!</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-9 wp-block-paragraph\">We are pleased to share that the Campus Connect<strong> </strong>event, held on Thursday, October 1st, was successfully completed with the participation of students from Ahmad’s Education.</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-10 wp-block-paragraph\">Ahmad’s Education has already collaborated with WordPress and successfully completed two batches. This event was another valuable opportunity to strengthen our collaboration, share knowledge, and inspire students to explore new learning opportunities.</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-11 wp-block-paragraph\">A heartfelt thanks to the WordPress team, the organizers, and all the students who contributed to making this event successful.<br />Looking forward to more collaborations and learning opportunities together!</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large is-style-default wp-duotone-unset-1\"><a href=\"https://central.wordcamp.org/files/2026/10/group2-scaled.jpg\"><img alt=\"\" class=\"wp-image-16499417\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/10/group2-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/ahmadsEducation-scaled.jpg\"><img alt=\"\" class=\"wp-image-16499418\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/10/ahmadsEducation-1024x768.jpg\" width=\"1024\" /></a></figure>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<div class=\"wp-block-columns are-vertically-aligned-center is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center has-white-background-color has-background is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/abdullah-noman.jpg\"><img alt=\"\" class=\"wp-image-16499419\" src=\"https://central.wordcamp.org/files/2026/10/abdullah-noman.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/aminul.jpg\"><img alt=\"\" class=\"wp-image-16499420\" src=\"https://central.wordcamp.org/files/2026/10/aminul.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/atikur-rahman-geting-certificate.jpg\"><img alt=\"\" class=\"wp-image-16499424\" height=\"1536\" src=\"https://central.wordcamp.org/files/2026/10/atikur-rahman-geting-certificate.jpg\" width=\"2048\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/guies-3.jpg\"><img alt=\"\" class=\"wp-image-16499423\" src=\"https://central.wordcamp.org/files/2026/10/guies-3.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/guist-1.jpg\"><img alt=\"\" class=\"wp-image-16499421\" src=\"https://central.wordcamp.org/files/2026/10/guist-1.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large is-style-default\"><a href=\"https://central.wordcamp.org/files/2026/10/guist-2.jpg\"><img alt=\"\" class=\"wp-image-16499422\" src=\"https://central.wordcamp.org/files/2026/10/guist-2.jpg\" /></a></figure>\n</figure>\n</div>\n</div>\n</div></div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 11:04:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"ATIKUR RAHMAN\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Why Fast AI Inference Is a Game Changer for Developers\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563865\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://openchannels.fm/why-fast-ai-inference-is-a-game-changer-for-developers/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:332:\"In tech, speed can make all the difference. One topic that doesn&#8217;t get enough attention is just how much faster AI inference is changing the way developers work. Training AI models still grabs the headlines with all the talk about big clusters and huge data sets, but the real impact for most developers happens when [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 09:48:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"Dennis Snell: Radical explorations in agentic development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"https://fluffyandflakey.blog/?p=4166\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://fluffyandflakey.blog/2026/10/19/radical-explorations/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:57783:\"<p class=\"wp-block-paragraph\">In mid-April 2026 my employer started a project called “Radical Speed Month” to step away from our existing structures and processes, make space for people to dive more deeply into AI tooling, and try to build new or sleeping ideas. My participation in this experiment ran until late September and I stacked up a lot of explorations without having written about them or about the process. In this post I’d like to highlight some of the results of this time and share some learnings.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Selected lessons</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Massive agentic deployment demands heavy storage and generic compute capacity — inference is not the only bottleneck. This is necessary to support massively parallel checkouts of code, benchmarking, analysis of other software and data, running hierarchies of thousands of test workers and headless browsers, generating and analyzing image and video artifacts, creating indexes, and more.</li>\n\n\n\n<li>Instructing an agent to “find the five hidden defects” is more effective at finding real issues than asking if there are any hidden defects. They may return false claims, but they try to answer the questions they are prompted — it’s not that different than the comparison between asking someone what in their day brought them a smile, or what was difficult for them, rather than asking “how was your day?”</li>\n\n\n\n<li>Agents with web searching capabilities are powerful knowledge-retrieval and aggregation tools. Reports they generate to aid in developing code can be more effective than asking the agents to generate the code directly.</li>\n\n\n\n<li>Models today are incredibly powerful, but guiding human insight is also powerful. Autonomous agentic activity demonstrated a tendency to produce more evidence of accomplished work than actual accomplished work. In a strange way this might reflect the training dataset: corporations must also guard against the dangers of overly-burdensome paperwork.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Projects</h2>\n\n\n\n<p class=\"wp-block-paragraph\">All of the projects here were almost entirely built by AI agents, but with my guidance and supervision. Therefore, credit for each of them does not rest entirely with me. However, for the sake of brevity I will omit mentioning in each one that AI tooling was the actual producer.</p>\n\n\n\n<span id=\"more-4166\"></span>\n\n\n\n<p class=\"wp-block-paragraph\">Each project below is assigned a truly unscientific evaluation:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> The project succeeded with clear value.</li>\n\n\n\n<li><img alt=\"🤷‍♂️\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f937-200d-2642-fe0f.png\" style=\"height: 1em;\" /> The project completed its goals, but the value is unclear.</li>\n\n\n\n<li><img alt=\"⏳\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/23f3.png\" style=\"height: 1em;\" /> The hard work has completed, but I need to close the loop and deploy it.</li>\n\n\n\n<li><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> The idea is sound but not ready; it needs more development.</li>\n\n\n\n<li><img alt=\"❌\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/274c.png\" style=\"height: 1em;\" /> The project failed to bear fruit for any reason.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">My personal favorites:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#fix-a-driver-bug\">Fix bugs in proprietary hardware drivers</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#gather-empirical-data\">Gather empirical evidence to guide development decisions</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#crawl-it-all\">Stream real-world HTML from Common Crawl</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#php-gameshark\">Provide deep insight into PHP script execution</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#wp-de-rtc\">Rapidly prototype a comprehensive collaborative editing environment for WordPress</a></li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Tools</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Because I expected a short availability for the enhanced AI access, I prioritized building, early on, tools whose value would outlast the project. Generally I prefer working in offline or local environments, so I built archivers for several services which are only available when connected to the Internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While MCP servers were very popular at this time, I have always been unhappy with the load centralization and amplification they create. The same is true for any online resource against which agents perform searches. My intuition is that it’s more considerate to those services to make one batched update, to download all new data since the last sync, than it is to make repeated queries which might overwhelm their servers and fetch the same resources over and over.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Being offline and local, the archivers are extremely fast and operate in the terminal where I prefer to interact.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> GitHub archive</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Finding GitHub’s search functionality lacking, and wishing for a chronological stream of my activity, I built <code>github-archiver</code> so I could have the tools and performance I wanted. This initially supported searching through PRs, issues, and comments, as well as rendering my own activity in a reverse-chronological view. I eventually added two additional views for replies: people I replied to, and people who had replied to me. This gives me great awareness of my recent conversations and has helped me to avoid losing conversations. Sometimes I struggle to find a PR that I meant to follow-up on, but it disappears from my GitHub notifications and I can’t remember the exact wording that will turn it up in a search result. I even tend to forget in which code repository it was left, so my tool aggregates activity across all archived repositories.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The basic design is a compressed HTTP cache of the GitHub API. When fetching or updating, it respects rate limits and leans on HTTP headers to avoid wasted transfers. After some work with banking APIs several years ago, I found that storing raw HTTP responses proved more flexible than parsing into a custom internal data type, as it lets me rewrite logic in the app later without having to re-download the entire archive. This came in handy several times as I expanded the search index and added more functionality.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The tool renders GitHub content as richly-formatted and highlighted text in a console unless running outside of an interactive TTY. It renders Markdown and HTML content into this rich text format and lays out meta elements in a meaningful way. Its speed, zero-network dependence, and minimized output make it a good fit for agents that would otherwise be hammering GitHub’s API, waiting, and wasting tokens on irrelevant content.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter\"><img alt=\"github-archiver renders PRs, Issues, comments, and line-level comments into the terminal with parsed markup, syntax highlighting, code snippets, and links created via ANSI terminal codes. It provides an alternative to the slower browser-based interface.\" class=\"wp-image-4214\" height=\"409\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-3.11.29-PM.png?resize=740%2C409&#038;ssl=1\" width=\"740\" /></figure>\n</div>\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Trac archive</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Just like the <code>github-archiver</code>, I built a <code>trac-archive</code> for <a href=\"https://core.trac.wordpress.org\">WordPress’ Trac</a> system. It is feature-similar to the GitHub archiver, but provides an additional perk: because bots relay messages from GitHub back into Trac, issues often have two markup formats in use simultaneously. My <code>trac-archive</code> first parses its content according to Trac’s own system, but then it additionally parses Markdown where it finds it. It shares much of the rendering logic with the <code>github-archiver</code> and provides a clearer experience than the web view due to the additional parsing, syntax highlighting, and ability to exclude bot traffic from the results.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-3.49.04-PM.png?ssl=1\"><img alt=\"Like the github-archiver, the trac-archive renders tickets into the terminal with parsed markup, syntax highlighting, code snippets, and links created via ANSI terminal codes. It provides an alternative to the slower browser-based interface and in many ways a more usable one due to the way Trac aggregates content from GitHub.\" class=\"wp-image-4228\" height=\"459\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-3.49.04-PM.png?resize=740%2C459&#038;ssl=1\" width=\"740\" /></a></figure>\n</div>\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Review the evolution of a series of commits over time</h4>\n\n\n\n<p class=\"wp-block-paragraph\"><code>git-sequence-patch</code> was used to help me understand the full scope of the WordPress collaborative editor project. Since many large features or projects span many commits and possibly even months or years of work, this tool reads a number of <code>git</code> commit SHAs and will build a fictitious patch that more or less represents how the entire project would be proposed were it to be proposed against the latest branch head. Another way to look at this is to generate one massive revert commit for the original feature and all descendant changes to it since its inception.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is a project I had been wanting to build for a long time; for each of the given commits, it tracks which lines were changed by the commits, and then steps forward through the branch history, noting when other commits also modify or remove those lines. Once it completes at the branch head, it prepares a patch to replace all of those lines with the code that was there before the original patch, and reverse the patch. This means that it doesn’t produce a patch that would actually merge, but it produces a patch that’s useful for understanding the full scope of how a change evolves over time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It’s line-oriented and so would miss some obvious scope. For example, if tracing the sequence for a new function, it will miss a later change which calls into that function. This would actually be possible to add to the tool as an enhancement, but it wasn’t necessary for my purposes at the time and I think it would remain ideally an option rather than a default behavior.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I spend a lot of time trying to quickly understand entire systems that I didn’t write or have any experience with, and this tool is a delight for answering the question: “how has this change evolved through time?”</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"crawl-it-all\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Analyze real-world HTML from Common Crawl</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To better test the HTML API against real HTML documents, I built <code>cc-analyzer</code>, which feeds data from the Common Crawl index into a user-supplied PHP script. This operates in two modes: streaming and batched. In streaming mode it continuously sends HTML documents from the archive into the analysis script. In batched mode, it saves documents from the archive into a subdirectory and then may be invoked again to re-run those documents through specific analysis scripts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This project has greatly benefited the testing and verification of the HTML API, and informed decisions about what actual HTML syntax patterns exist on the web and what concerns are practical and which are esoteric. Throughout this grand experiment I have examined hundreds of thousands of HTML documents to test the HTML API code, to understand reported and actual text encodings of websites at large, to benchmark changes and optimizations for the HTML API, and to understand parsing needs of real HTML documents.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Instantly search code from the WordPress ecosystem</h4>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://veloria.dev\">Veloria.dev</a> (formerly WPDirectory.net) provides fast code search across all of the plugins and themes listed on the WordPress directory. It was experiencing elevated outage rates and I decided at the start of September to recreate it locally as a single binary with a simple compressed offline archive. Previous efforts to <a href=\"https://github.com/markjaquith/WordPress-Plugin-Directory-Slurper\">slurp the directory</a> left efficiency gains on the table and output around 120 GB of data on the filesystem. By taking advantage of available concurrency, streaming computation as resources are downloaded, pruning the stored files to those which were being indexed, and saving into a custom compressed binary object, my <code>wp-code-search</code> tool was able to archive the directory in five hours storing only 5 GB among three data files: a compressed archive of the source files, a search index, and a metadata archive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This idea originally came from Dan Luu, who <a href=\"https://danluu.com/perf-opt/#build-an-index\">commented</a> that “<em>if we&#8217;re repeatedly searching for text on a computer, the obvious thing to do to speed that up isn&#8217;t to write a native code compiler for regex matching, it&#8217;s to create an index</em>.” Code searches across the entire directory typically return within 10 ms, output syntax-highlighted snippets from the files in which they are found, and the tool can extract those files or entire plugins from the compressed archive. The index is sorted by active installs so the most-deployed results appear first.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.01.11-PM.png?ssl=1\"><img alt=\"When performing searches on the WordPress directory, the results print out with the name of the file the result was found in, how many active installs the plugin reports, and a syntax-highlighted snippet of the code with the search matching underlined.\" class=\"wp-image-4233\" height=\"215\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.01.11-PM.png?resize=740%2C215&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Basic regex searches execute in milliseconds.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">This tool has become an invaluable daily driver for me as I refactor Core WordPress internals and want to avoid needlessly breaking existing code.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end of September I had another long-shot idea: could the ideas making the text search so fast be mixed with structural queries so that I could perform data-flow and control-flow analysis on the code? Turns out that yes, with another 5 GB sidecar index, and a custom WordPress-specific query syntax this was not only possible, but practical with many complicated queries executing in anywhere from a few seconds to a few tens of seconds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There’s a lot of power in this query syntax to identify complicated code structures and I still have to learn how to generate the kinds of queries I want to. I built the structural code search to aid in discovery of risky code patterns to harden as part of my work improving WordPress’ security stance.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.06.36-PM-1.png?ssl=1\"><img alt=\"The custom query syntax provides constructs for describing data flow and control flow. It resembles structural query syntaxes from other languages.\" class=\"wp-image-4236\" height=\"660\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.06.36-PM-1.png?resize=740%2C660&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">A custom syntax makes possible complicated structural queries on the code and values passing through it.</figcaption></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.05.50-PM.png?ssl=1\"><img alt=\"Some results from the more powerful queries could have been more-efficiently found with string-based searches, such as when one function call is found as an argument to another function call, and on the same line.\" class=\"wp-image-4241\" height=\"311\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.05.50-PM.png?resize=740%2C311&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Executing returns results we could have matched with a regex.</figcaption></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.13.12-PM.png?ssl=1\"><img alt=\"Structural queries detect far more than same-line lexical results. They ignore whitespace and can follow other patterns, such as when the result of a function call is later passed into another function as an argument.\" class=\"wp-image-4238\" height=\"123\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.13.12-PM.png?resize=740%2C123&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Executing also returns matches not possible through lexical pattern matching alone, tracing the flow of data and control throughout a program.</figcaption></figure>\n</figure>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🤷‍♂️\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f937-200d-2642-fe0f.png\" style=\"height: 1em;\" /> Text-mode access to the modern web</h4>\n\n\n\n<p class=\"wp-block-paragraph\">My <code>zs</code> tool performs web searches and downloads rendered HTML pages in the terminal. Fascinatingly enough, when I attempted to start this project I tried explaining very clearly that I wanted to adhere to the terms of use for all services, that I wanted to respect the remote servers providing the content, and that this was a user-agent acting on my behalf to perform queries in the terminal instead of a browser. Unfortunately, it seems like the instructions to follow the rules were misinterpreted as attempted bypasses and overly-refused.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Regardless, I was able to create this non-GUI browser and build up enough of the Web Platform to render the pages I wanted to view. When Captchas and other verification interstitials appear, they render inline into the terminal via terminal raster commands. I’m able to indicate which boxes contain the bus, or motorcycle, or a bridge, which Google seems really intent on learning, and continue with text flows and shell pipelines.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My motivation for building this was to perform web searches from the CLI, but once I had the mechanisms in place to interact with the search engines, I realized I could also use this to grab dynamically-rendered pages. For any given URL, a page loads, executes scripts, and renders until the JavaScript event queue empties or a timeout trips, and then the final DOM serializes into the HTML output.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This makes the tool more valuable than my typical <code>curl</code> flow, which too-often downloads an empty HTML page reminding me that I should be using JavaScript. Because it implemented so much of a browser’s internals, I added a feature to extract the visible text content of the rendered page, something which is surprisingly difficult to download without a full browser and CSS engine, and something which is really valuable when trying to pipe documentation pages into coding agents.</p>\n\n\n\n<p class=\"wp-block-paragraph\">All in all it’s a bit buggy and I would like to start over based on what I learned along the way. It still works <em>sometimes</em> and it’s valuable to me when web pages return otherwise-empty mountains of script contents.</p>\n\n\n\n<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.05.37-PM-1024x957.png?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.05.52-PM-757x1024.png?ssl=1\" tabindex=\"0\" /></figure></div></div></div></div></div>\n\n\n\n<h3 class=\"wp-block-heading\">WordPress.com</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"⏳\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/23f3.png\" style=\"height: 1em;\" /> Clarify wording in notification messages</h4>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress.com sends notifications about comments, likes, follows, etc., and sometimes the wording is awkward or inconsistent. I generated a report classifying emotional content of the wording and suggested improvements to better inform the reader of what they could or needed to do. It was effective at joining snippets of strings that are concatenated together throughout the code and provided useful insights. It also provided good suggestions for updates that focused on removing anxiety and clarifying possible actions to take in response to the alerts (e.g. replace “Renewal Failed” with “Payment did not go through; update by May 18 to keep your plan active”). Unfortunately those updates are still on my backlog to deploy.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"⏳\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/23f3.png\" style=\"height: 1em;\" /> Migrate confused legacy data to simplify runtime code</h4>\n\n\n\n<p class=\"wp-block-paragraph\">There are old notification records in the database with conflated and truncated values, and these require complicated code when rendering them to make sense of the confused properties. I was hoping that it would be possible to have the AI examine these broken records and the generating code and provide clear guidance on how to update them. Among 3,000 old records in the database, it proposed seventeen cases for recovery and fixing. Unfortunately this also sits in my backlog to assess and apply.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fix translation issues and typos</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Developers frequently concatenate separately-translated strings which lead to confusing translations. I ran an analysis for this kind of translation issue inside the notifications source code and also for typos and other mistakes. This produced a list of around fifty bug-fixes, including for a missing namespace specifier that was broken for more than a decade and which hadn’t been noticed in error logs, malformed HTML tags which had been hard-coded in string literals, plenty of concatenated translated strings, broken interpolation placeholders, <em>missing</em> calls to the translation function, and missing null checks. This was deployed in May to the production system.</p>\n\n\n\n<h3 class=\"wp-block-heading\">WordPress, the open-source project</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> Generate automatic previews for dev-docs changes</h4>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Playground runs a copy of PHP and WordPress entirely in the browser via compilation into a WASM environment. It provides testable previews for WordPress and Gutenberg PRs. Missing has been a way to preview changes to the generated developer documentation, which is notoriously difficult to get running at all, let alone dynamically in a browser. I proposed a demonstrator in <a href=\"https://github.com/dmsnell/wordpress-develop/pull/29\">#29</a> that does just that through a GitHub Actions workflow on PRs. It has inspired follow-up, but due to the need to ensure a maintainable solution, is still pending deployment.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> Harmonize the ignore ruleset across <code>git</code> and Subversion</h4>\n\n\n\n<p class=\"wp-block-paragraph\">The official WordPress source code lives in Subversion with a <code>git</code> mirror. The <code>.gitignore</code> and Subversion ignore rulesets are fundamentally distinct from each other, notably in that <code>git</code> ignore patterns apply recursively through a file tree. I attempted to use AI to harmonize the rulesets. Some adjustments were made, but the entire set still needs careful review.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Visualize per-package activity within Gutenberg</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To better understand per-package activity within the Gutenberg editor project, I produced <a href=\"https://fluffyandflakey.blog/2026/06/11/gutenberg-package-activity/\">a visualization showing commit activity</a>.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"php-gameshark\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Provide deep insight into PHP script execution</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Inspired by my childhood <a href=\"https://en.wikipedia.org/wiki/GameShark\">Gameshark</a>, I built a PHP extension to improve my ability to debug and analyze PHP script runs. This started as a way to compare two runs of a given script, but expanded into a set of related but distinct modes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Differential mode</em> compares which functions were called and how many times across two different script runs; this could be useful for performance optimizations or comparing what runs for two different code paths and was built initially while working on page renders vs API call responses.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Trace value</em> records every function or method call whose arguments contain a requested value. It tracks user space as well as builtin functions and was built to help identify code paths which send untransformed data where it shouldn’t reach. A <em>follow transformations</em> option tracks not only the given value, but also common escaped, encoded, serialized, quoted, slashed, and other variations of it. This is a clever security tool for finding out where and how unwanted data is passed around.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Invariant mode</em> takes a PHP file with “hooks” that attach to functions and methods, either during entry into those contexts or when returning from them. They are supplied the values to the arguments, the <code>$this</code> value if a method, and the return value if a post hook. This enables a novel approach to applying software contracts on code with neither the production runtime overhead nor the noise from the contract-enforcement. This was loosely inspired by <a href=\"https://clojure.org/guides/spec\">Clojure’s <code>core.spec</code></a>. Because the hooks file is user-space PHP code with access to global state, this provides mechanisms for enhanced testing and analysis code, and when registering a shutdown handler in PHP, can print reports at the end of script execution. Hooks may also raise exceptions to halt execution when any desired invariant is violated, such as when <code>preg_match()</code> receives a pattern that might be attempting to parse HTML.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Unused runtime coverage mode</em> generates a report of all loaded identifiers which were never read or executed during a script execution. A sampling option can be used in production to assemble such a report, probabilistically, over time. This mode was designed to find effectively dead-code that might be lurking behind runtime conditions which can never actually run due to real data distributions. For example, a function which is only ever called before a given date, when the given date is several years in the past. Static analysis will miss this while a month of production sampling with no calls will provide evidence that it’s safe to remove the function, that no other strange or unexpected call-paths are still calling it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Trace allocations</em> mode traces heap allocations made by PHP during a script execution. It immediately surfaced unnecessary allocation in <code>wp_is_numeric_array()</code>, which was promptly eliminated in [<a href=\"https://github.com/WordPress/wordpress-develop/pull/12100\">#12100</a>].</p>\n\n\n\n<p class=\"wp-block-paragraph\">This extension has provided incredible insight into how WordPress and other PHP scripts run, and I’ve only scratched the surface of how I can take advantage of it.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> Introduce dynamic security policies into PHP with eBPF to isolate plugin code and extensions</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Like the <code>php-gameshark</code> extension, I built a modified <code>php</code> binary which coordinates with eBPF in the Linux kernel to apply dynamic security policies and create isolated security domains within executing PHP code. There is no logical separation between executing the Core WordPress code and the code from plugins running on a site. This is a security challenge because the two kinds of code warrant different trust, and a site operator may want to assign unique trust and capabilities to different plugins.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This extension provides a <code>wp_runtime_security_apply_policies()</code> function which registers sandboxing rules against files whose source code matches the provided glob. It allows disabling network access, shell execution, sending of emails, reading uploaded files, and writing uploaded files demonstrating a path towards securing WordPress sites from errant or malicious plugins, as well as an explicit opt-in capability model for plugins as they have need. It doesn’t just protect user-space PHP code either; thanks to the fact that policy enforcement occurs within eBPF, it can also apply the same policies against compiled PHP extensions running on the host, assuming that the extensions are not actively attempting to exploit the guards (the protection is aimed at security vulnerabilities within the commonly-deployed PHP extensions, not against potentially-malicious extensions).</p>\n\n\n\n<p class=\"wp-block-paragraph\">I built this extension after a discussion with Lynn Griffith at WordCamp US in late August. It seems promising but is under-developed and needs production testing. As it relies on eBPF, it only supports Linux environments, ruling out Windows, BSD, and macOS-based hosts.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.51.38-PM.png?ssl=1\"><img alt=\"User-space PHP code can change the current policies by passing a descriptor object to the extension showing which file globs are to have which privileges.\" class=\"wp-image-4269\" height=\"387\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.51.38-PM.png?resize=740%2C387&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Policy rules stack: code deeper in the call stack may further restrict the permissions, but cannot expand them.</figcaption></figure>\n</div>\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Benchmark HTML parsing optimizations against realistic data from the Internet</h4>\n\n\n\n<p class=\"wp-block-paragraph\">With the aid of <code>cc-analyzer</code>, I automated the benchmarking of numerous optimizations that we have explored over the years with the HTML API, mostly changes to the internal data structures and how attributes are represented during the parse. The AI tooling provided the run-scripts for <code>cc-analyzer</code>, invoked it, and gathered the results. It also collected PRs that I had proposed (using the <code>github-archiver</code>) since May 2023 so that I didn’t have to find them.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fuzz-test the HTML API</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I fuzz-tested the HTML API, finding several unreported bugs, including <a href=\"https://github.com/WordPress/wordpress-develop/pull/11982\">easy-to-overlook defects in the code</a>. Fuzzing in this way also prevented a number of defects with <a href=\"https://make.wordpress.org/core/2026/10/07/progress-report-wp_kses/\">the rewrite of <code>wp_kses()</code></a>. This complements the existing spec-compliance tests against the <code>html5lib</code> test suite, practical tests against real HTML from the web, and a unit-test suite covering intentional behaviors.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"❌\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/274c.png\" style=\"height: 1em;\" /> Scaffold fuzz-testing in Gutenberg</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I attempted to build a generalizable fuzz-testing infrastructure for the Gutenberg editor. This was an extended autonomy agentic session that ultimately produced a good-looking dashboard with nothing but false-alarms. I tried to establish a framework in which other developers could easily add new generative categories and the system would run new fuzzers for them, compare outputs, and triage failures. AI parallelism made for impressive work, but in this early project I was unable to accomplish my goal and gave up on the idea.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Port data sync libraries into PHP</h4>\n\n\n\n<p class=\"wp-block-paragraph\">As an experiment in goal-oriented design, ten distributed data structure libraries were ported into PHP userspace code to aid in building a demonstrator for <a href=\"https://make.wordpress.org/core/2026/10/14/real-time-collaboration-a-guide-to-sync-engines/#:~:text=the%20same%20time.-,Engine%202:%20DE%2DRTC,-Summary:%20Most%20similar\">the DE-RTC prototype</a> [<a href=\"https://github.com/WordPress/wordpress-develop/pull/12334\">#12334</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79602\">#79602</a>]. With minor caveats, this built working copies of <code>yjs</code>, <code>automerge</code>, <code>loro</code>, <code>diamond-types</code>, <code>diff-match-patch</code>, <code>json-patch</code>, <code>json-joy</code>, <code>sharedb-json0</code>, <code>prosemirror-collab</code>, and <code>collabs</code> which passed their upstream test suites when they were converted to call the PHP code. Eight of the libraries were completed within a few days, but <code>loro</code> (the library I was primarily interested in) and <code>json-joy</code> held out the longest, taking weeks to complete. They appeared stagnant for the bulk of that time and rapidly finished passing the remaining tests in a burst at the end. While I had originally built a prototype collaborative editor with <code>yjs</code> (which is what the existing project team had chosen to use in JavaScript), once <code>automerge</code> completed I was able to swap out the synchronization primitive and later do that again with <code>loro</code>, adding the capability to make more semantically granular changes and merges. This work was almost entirely hands-off and ran in the background until it was completed; every ten minutes it updated an HTML dashboard showing status and operating notes.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fuzz-test the proposed collaborative editor for WordPress</h4>\n\n\n\n<p class=\"wp-block-paragraph\">From the end of April until October, I paired with Dan Luu to fuzz-test the collaborative editor proposal, and we uncovered an array of issues which ultimately led to changes in the timeline for the project, as a number of the defects were nontrivial to solve. Most of the fuzz infrastructure was built by Dan, while I attempted to coordinate the reproducible bug reports with the rest of the team and to propose fixes. The fuzzing machinery produced effectively no false positives due to the triage and reproduction steps built in. It also provided the visuals for theoretical bugs which are hard to diagnose manually with a keyboard and mouse, but which actually occur frequently in concurrent systems.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This was a high-reward project for the investment because, while AI was dominant in the early code generation, once the testing suite was established, it was able to continue to operate without much additional AI input, and it’s possible to run without <em>any</em> AI inputs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It highlighted two aspects of fuzz-testing: the more robust the code being tested already is, the more valuable the fuzz-testing will be; and the more frequently a bug is likely to materialize, the more quickly fuzz-testing will find it. There is a good match here between the needs and the operating characteristics.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Actually, Dan and I were originally looking at working on other projects for this <em>Radical</em> experiment. I had suggested that we use the nascent collaborative editing project to organize our notes and work within a WordPress site — to “dogfood” the editor. We pivoted to this testing and design support role only because of problems which immediately appeared as we tried to use it.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"wp-de-rtc\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Prototype a comprehensive collaborative editing environment for WordPress</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To demonstrate another approach to collaborative editing, I instructed an agent to follow my core principles and requirements for the task and build a prototype. At first I wanted the agent to mimic forming its own company, planning, dividing labor, and harmonizing productivity, but as this ran for weeks it kept descending into a cycle of producing more and more meaningless paperwork with less and less actual work. Around the end of May I rebooted the project with far more direction and guidance, replacing the goal-oriented and hands-off approach with a <em>human-driving-the-loop</em> method. This proved more effective and in two weeks I had a working prototype that demonstrated every aspect that I considered important and lacking in some of the other public proposals. At some point I will share a version of an internal post I wrote summarizing this work. It proved influential on the project and I believe that the continued development of collaborative editing is heading in a stronger direction as a result.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For years I have struggled to adequately convey why specific principles and requirements are important, but having a visual prototype made it feel real in a way that persuasion had failed me. The amount of up-front work to produce this prototype had been obstructive for years, and without the agent I would not have been able to communicate the tradeoffs involved in its approach.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Restore developer documentation generation by updating deprecated legacy code</h4>\n\n\n\n<p class=\"wp-block-paragraph\">At the end of February I had <a href=\"https://make.wordpress.org/core/2026/02/25/developer-documentation-restored/\">restored WordPress developer documentation</a> which had been stale for two years due to failing build scripts and deploy scripts. While this work resolved most issues and unlocked updated docs for WordPress 6.9, there remained a few unresolved issues which led to specific submodules being excluded from those docs. In mid-May, <a href=\"https://github.com/dmsnell/phpdoc-parser/commits?author=codex\">fixes for the remaining issues</a> were applied to the dependent projects which removed all remaining barriers. All documentation was updatable again and the scripts could run in the latest PHP versions without crashing.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Prevent mistakes in commit messages and automate the repetitive parts of writing them</h4>\n\n\n\n<p class=\"wp-block-paragraph\">After seeing my colleague Jon Surrell’s <code>neovim</code> linter for writing <a href=\"https://make.wordpress.org/core/handbook/best-practices/commit-messages/\">WordPress commit messages</a>, I ported his linter into a single-binary/stdout LSP usable in any LSP-supporting editor. This expanded the work Jon did and built upon work from my other tools to show inline previews of Trac tickets and GitHub PRs. It included new auto-fixers for formatting and line ordering and I use this today to prepare my commit messages, avoiding mistakes I have overlooked in the past.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"gather-empirical-data\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Gather empirical evidence to guide parsing decisions in the HTML API</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I used an instrumented custom build of PHP and <code>lexbor</code> in September to answer a perplexing question: “how many tokens of lookahead would be required for the HTML Processor to fully-parse a given percentage of all HTML documents?” This stems from the tricky <em>re-parenting</em> issues in HTML tree building, where a syntax form at the end of the document could appear towards the start of parsed tree structure. The instrumented code examined when <code>lexbor</code> ran its “adoption-agency algorithm” and tracked how much further into the document the current token appeared after the token associated with its actual parent node.</p>\n\n\n\n<p class=\"wp-block-paragraph\">An hour-long run of <code>cc-analyzer</code> showed that among 70,000 documents, approximately 1,000 require at least 1-token lookahead, only about 250 could parse with 5-token lookahead, and 13 would have required more than 10,000-token lookahead! In one case, a document contained an un-closed <code>&lt;b></code> tag near the start of the document, and then 400 kB and 35,000 syntax tokens later, triggered re-parenting — no default behavior will offer 35,000-token lookahead.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The outcome of this run was disappointing, but the data was invaluable and prevented wasting time implementing a lookahead mechanism that wouldn’t meaningfully benefit consumers of the API.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.10.35-AM.png?ssl=1\"><img alt=\"Of the documents requiring lookahead, more than half of them require more than 20-token lookahead. Real HTML on the web is not tamed by a few tokens of lookahead.\" class=\"wp-image-4347\" height=\"790\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.10.35-AM.png?resize=740%2C790&#038;ssl=1\" width=\"740\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.30.52-AM.png?ssl=1\"><img alt=\"Agents were helpful in producing explanatory failure reports to investigate particular error cases. They can show snippets of the document triggering re-parenting and explain which rule in the spec was unsupported and led to the bailout.\" class=\"wp-image-4349\" height=\"760\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.30.52-AM.png?resize=740%2C760&#038;ssl=1\" width=\"740\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.49.31-AM.png?ssl=1\"><img alt=\"\" class=\"wp-image-4350\" height=\"806\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.49.31-AM.png?resize=740%2C806&#038;ssl=1\" width=\"740\" /></a></figure>\n</figure>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Review and scrutinize code change proposals</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Throughout the entire experiment AI was providing valuable code review and patch preparation. WordPress security fixes are typically backported to WordPress 4.7, which covers 25 released versions <em>and </em><code>trunk</code>. Many of these support older versions of PHP missing standard-library features that newer code depends on, and lack WordPress functionality that newer code depends on. When preparing a backported patch, I created reports detailing which features and functions had to change at each WordPress release, and what was driving that need. I found these to be more useful than having agents automate the backporting as fewer mistakes were overlooked when I was performing the changes with the assistance of the reports.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.29.22-PM.png?ssl=1\"><img alt=\"In one report, the agent lists for each version of WordPress, including the minimum-supported version for that release, issues with given code constructs or function calls. It indicates if there would be runtime issues and also if the syntax would fail to parse in the oldest-supported PHP version.\" class=\"wp-image-4352\" height=\"345\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.29.22-PM.png?resize=740%2C345&#038;ssl=1\" width=\"740\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.28.47-PM.png?ssl=1\"><img alt=\"Another report lists for each kind of code construct, at which release of WordPress it’s first supported, and which lines of code in the proposed patch must be changed in order for it to run on older releases.\" class=\"wp-image-4353\" height=\"395\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.28.47-PM.png?resize=740%2C395&#038;ssl=1\" width=\"740\" /></a></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">AI code review was invaluable though during the refactor of <code>wp_kses()</code> within WordPress. For weeks I instructed it to find the remaining overlooked defects that need resolving before merge, and it kept finding places to harden or fix the code. I never asked an agent to perform “code review” or indicate if a patch was ready to go. Instead, I instructed them to find hidden defects that I wasn’t sure existed, but when told to return three items, they would do it! I consider these kinds of situations among LLMs’ greatest strengths, when false negatives are more costly than false positives, and when validating claims is trivial. Every issue the agent claimed became a test that proved or disproved it and now guards against regression.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Simplenote and Simperium</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Implement well-defined feature requests in unfamiliar code</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To explore autonomous feature development, I had an agent resolve a concrete bug report describing difficulty copying content from historic revisions of a note [<a href=\"https://github.com/Automattic/simplenote-electron/pull/3358\">#3358</a>]. This kind of enhancement/fix was frustrating previously because it touches numerous parts of the codebase I was unfamiliar with. The models picked up a number of places I would have overlooked when working on the problem.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Document confusing data flows in unfamiliar projects</h4>\n\n\n\n<p class=\"wp-block-paragraph\">The data service powering Simplenote was written with untyped Python code, and partial duck-typed data structures are passed around which can make code comprehension dizzying. While I wanted to avoid AI-generated code changes, given how critical the backend is, in late May I produced comment-only changes annotating data types and providing explanatory comments where certain code constructs were unclear. This was a low-effort way to pass along some insight about the code in hopes that it makes someone else’s job clearer in the future, as I have not maintained this codebase for years.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Random</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🤷‍♂️\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f937-200d-2642-fe0f.png\" style=\"height: 1em;\" /> Monitor Codex usage</h4>\n\n\n\n<p class=\"wp-block-paragraph\"><code>codex-usage-report.py</code> scans the <code>~/.codex</code> directory and summarizes token counts, the models which were used with them, and approximates the dollar cost of that usage based on current API pricing.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Export Codex usage into a searchable format</h4>\n\n\n\n<p class=\"wp-block-paragraph\">As the radical experiment was drawing to a close, I created a Codex exporter which dumps the session data into a giant single-file HTML archive where I can search interactively through the sessions and view the chat history, including tool calls, in a rendered view. I’ve referenced this several times as it’s quick and easy compared to logging into a server, finding the right session, and searching through its history.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Run inference on unsupported legacy hardware</h4>\n\n\n\n<p class=\"wp-block-paragraph\">My old MacBook Pro came with a dedicated Radeon GPU and sits idle or off most of the time. <code>llama.cpp</code> doesn’t support the older GPU and so I wanted to see if I could get it running. It did produce a working copy that runs local inference on the Radeon GPU, but in practice it underperformed the CPU-based inference for the same models. With only 4 GB of VRAM, it couldn’t load enough weights at one time to operate without constantly transferring data, and the transfer overhead was too high. I explored different means of sharing work between the CPU and GPU, but they were fighting for memory bandwidth.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While this didn’t provide me with a low-and-slow inference engine, it demonstrated the ideas and ran the experiments which is something I had little patience for, given that I expected poor usefulness in the best of cases.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"fix-a-driver-bug\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fix bugs in proprietary hardware drivers</h4>\n\n\n\n<p class=\"wp-block-paragraph\">At home I use my Fujifilm X-T3 as a webcam. It makes for a great quality video feed, but when Fujifilm updated the camera driver to integrate with one of the previous macOS updates, they introduced a memory leak which would end up using 90 GB+ of RAM plus swap by the end of a call and sometimes take down my system before I realized it. Knowing I had little hope of motivating Fujifilm to fix this, I made a binary patch to the driver and fixed the bug directly. This was directly inspired by <a href=\"https://arstechnica.com/gadgets/2017/11/microsoft-patches-equation-editor-flaw-without-fixing-the-source-code/\">stories of Microsoft fixing bugs</a> in components whose source code they had lost.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To my delight this fixed the memory leak and provided a plausible explanation. By decompiling the driver, the AI found a missing call to release JPEG data from each frame after passing it to <code><a href=\"https://developer.apple.com/documentation/coremediaio/cmiosamplebuffercreate\">CMIOSampleBufferCreate</a></code> — a classic memory bug. It predicted the impact of this defect and confirmed the rate of memory bloat with successive system dumps of the process. To add the missing release call it shuffled around some existing instructions to a region of padding bytes in the driver and then called into those; this freed up the bytes necessary for the instructions to call the release function. 44 bytes are written across three spans to make the fix, and this is a verifiable fix that I was able to apply without disabling the <a href=\"https://support.apple.com/en-us/102149\">system integrity protection</a> — an even better delight.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This has been quite possibly my favorite AI-assisted project. There is no way I could have imagined doing this work myself or having traction with Fujifilm to debug and fix this issue, and yet now I can have video calls run on for hours (were I to want such a thing) and memory use by the driver is fixed; it doesn’t fill up and then purge all of my RAM.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">A special thanks belongs to Automattic for providing this space in which to learn and explore, to OpenAI who provided elevated access to their frontier models and made it possible to preview what a future of abundant AI might look like, and to the <a href=\"https://jetstream-cloud.org\">Jetstream2 project</a> funded by US taxpayers who donated high-capacity compute resources to help improve the reliability and security of the WordPress project. I would also like to thank Dan Luu, who worked with me on this project and who taught me so much about practical generative/fuzz testing, and with whom I could never keep pace, in the best of ways.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Over the course of this time period I worked with GPT-5.4 all the way up to GPT-6-Astra, at ultra thinking levels on fast priority, and with Claude Sonnet 4.6–5.4. The earliest use came from <code>Qwen3.5-397B-A17B</code>, but I had also been running <code>Qwen3.5-27B-4bit</code> locally before the experiment started, and by the end was relying on <code>Qwen3.6-27B-4bit</code>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I’m thankful for the chance to reach into the past and demonstrate ideas I’ve had sitting on the back-burner, as well as to look towards the future and prototype designs I want to see turn into usable products.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 07:46:38 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Dennis Snell\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:26:\"Matt: Anthropic Employment\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155275\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"https://ma.tt/2026/10/anthropic-employment/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:213:\"<p class=\"wp-block-paragraph\"><a href=\"https://www.anthropic.com/research/employment-at-anthropic\">How employment is changing at Anthropic</a> is a fascinating read.<br /></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 17 Oct 2026 12:20:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Open Web vs Walled Gardens, Simplifying the Difference\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563759\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://openchannels.fm/open-web-vs-walled-gardens-simplifying-the-difference/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"A straightforward look at what the open web is, how it started, and why it matters for digital communities.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 16 Oct 2026 12:09:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"Matt: Pushing Standards\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155246\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://ma.tt/2026/10/standards/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2181:\"<p class=\"wp-block-paragraph\">We get a lot of flak at <a href=\"https://wordpress.org/\">WordPress.org</a> for supporting older PHP versions, but an area we&#8217;ve always pushed the frontier is in <a href=\"https://www.webstandards.org/\">Web Standards</a>, getting websites and browsers evolving together to make the web richer. Ever since I caught the religion from <a href=\"https://zeldman.com/\">Zeldman</a>, promoting more functionality in the browser has been a life mission. </p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s a little nerdy, but we wanted to do client-side media processing (use all that amazing Apple and Google silicon instead of burdening the poor servers) so we used something amazing Google created called <a href=\"https://developer.chrome.com/blog/document-isolation-policy\">Document Isolation Policy</a>. When <a href=\"https://wordpress.org/news/2026/08/mary-lou/\">WordPress 7.1 &#8220;Mary Lou&#8221; shipped</a> these features only worked in <a href=\"https://www.chromium.org/Home/\">Chromium</a>-based browsers and Mozilla and Webkit/Apple weren&#8217;t keen to support it, but since then <a href=\"https://github.com/mozilla/standards-positions/issues/1074\">Mozilla has expressed support</a> and <a href=\"https://github.com/WebKit/standards-positions/issues/399#issuecomment-5844114111\">WebKit has withdrawn their initial concerns</a>. WordPresser <a href=\"https://earthbound.com/\">Adam Silverstein</a> has been driving much of this work and <a href=\"https://github.com/WICG/document-isolation-policy/issues/8\">opened a WICG issue</a> to help move the standard forward and <a href=\"https://bugs.webkit.org/show_bug.cgi?id=325516\">formally requested that WebKit add support</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Hat tip: <a href=\"https://nomad.blog/\">Anne McCarthy</a> for helping with this post.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\">(If you want to see other crazy stuff we&#8217;re doing in browsers, check out <a href=\"https://wordpress.org/playground/\">WordPress Playground</a>, I think it&#8217;s actually the perfect web development environment for agents, which can then publish to <a href=\"https://spacefast.com/\">Spacefast</a>.)</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 16 Oct 2026 00:40:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"WordCamp Central: WordCamp Jinja 2026 Recap: Three Tracks, Two Days and Creative Currents on the Nile\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16286304\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"https://central.wordcamp.org/news/2026/10/wordcamp-jinja-2026-recap-three-tracks-two-days-and-creative-currents-on-the-nile/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:14108:\"<p class=\"wp-block-paragraph\">On 19th and 20th September 2026, the WordPress community gathered at Civil Service College Uganda, a venue close to River Nile, for the fifth edition of WordCamp Jinja. The event brought together more than 300 diverse participants across 2 days and 3 parallel tracks of sessions full of learning, collaboration and connection. In a city known for its flowing waters, creativity and ideas flowed too, as participants shared their experiences, explored new possibilities with WordPress and built relationships that would carry beyond the weekend.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our theme, “Embrace Creative Currents on the Nile: Where Inclusivity Fuels Creativity,” reflected the mix of people and ideas in the room. Students sat alongside developers, designers, writers, educators, entrepreneurs and experienced WordPress contributors. Across three parallel tracks, everyone could find a way to learn, share or build.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1271\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0667-1024x683.jpg\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Students and Creatives at the heart of WordCamp Jinja</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Nearly half of this year’s participants were students. Their presence was felt throughout the event, from the speaker sessions to the labs and hackathon tables. We had students from primary schools, secondary schools and universities joining us for this year&#8217;s WordCamp.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Some came to explore WordPress for the first time. Others arrived with projects, questions and skills they wanted to develop. Sharing the same spaces with people already working in technology and creative fields gave them an opportunity to learn directly from practitioners and see where their own interests might lead.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One student in attendance found a creative way to remember his experience. Fascinated by the WordPress ecosystem, its generosity and inclusivity, he drew all the sponsor logos by hand so he could remember them after the event. His drawings became a personal record of the community he had encountered at WordCamp Jinja, a small but memorable expression of the curiosity WordCamp Jinja inspired.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bringing young people into the community has been a continuing part of WordCamp Jinja’s work. Last year’s edition at Jinja Senior Secondary School brought the event closer to students; this year, their participation remained central even at a different venue. We hope the relationships formed over these two days continue at Jinja WordPress Meetups and in the projects students choose to pursue next.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1275\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0158-1024x683.jpg\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Event highlights</strong></h2>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Diverse Speaker Sessions</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Our speakers brought different backgrounds and experiences to the stage. Sessions opened up conversations about WordPress and the wider web, including how people use technology to create, teach, solve problems and build livelihoods.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The value of these talks was in the experiences behind them. Speakers shared what they had learned through their own work, answered questions and gave attendees ideas to take back to their studies, organisations and businesses. Thank you to everyone who prepared a session and made the journey to Jinja to share it with us.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-2 is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1273\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0053-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1274\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0084-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1276\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0488-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Charity Website Hackathon and Contributor Sessions</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The Charity Website Hackathon returned as one of WordCamp Jinja’s most practical activities. Participants and facilitators worked together on WordPress projects for organisations seeking to establish or improve their online presence. The teams had to think about real needs: what information a visitor should find, how to organise it and how the organisation could keep its site useful after the event.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For newer participants, this was a chance to learn by working through a real project with support close at hand. For experienced developers and designers, it was a chance to mentor others and put their skills to work for the wider community. The work begun at the hackathon can continue beyond the conference as teams and organisations develop their websites further.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1291\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1052-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1280\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1059-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">Contributor activities connected that local work to the wider WordPress project. Attendees explored the idea that contributing to open source goes beyond writing code: people can help through photography, translation, testing, documentation, training and community work. There were a lot of new contributors who were taken through the contribution journey by table leads. We hope that for those that took their first steps, WordCamp Jinja will be the beginning of a longer contribution journey.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-2 is-cropped wp-block-gallery-5 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1277\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1041-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1279\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1050-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Hands-on Labs</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The Hands-on Labs offered a different pace from the speaker sessions. Instead of only listening, participants could practically follow a facilitator on state of the art computers, try something themselves and ask for help when they needed it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That kind of guided practice matters, especially for people who are new to a tool or trying to turn an idea into something they can build. Thank you to the facilitators who prepared the activities and worked directly with participants, and to the volunteers who helped make the sessions run.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-6 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1272\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0641-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Memorable moments, connections and networking</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Some of the weekend’s most useful moments happened away from the front of a room. Over lunch, in the corridors and between activities, attendees met people from other communities, exchanged ideas and caught up with friends they had met at earlier WordPress events.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1300\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1585-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-7 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1293\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0438-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1295\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0648-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1296\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0718-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1294\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1575-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1297\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0773-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1298\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_9896-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">For a student attending for the first time, a conversation with a developer or designer can make a possible career feel closer. For returning community members, it was a chance to meet new collaborators and hear perspectives they might otherwise miss. Those connections are part of what keeps WordCamp Jinja going after the closing session.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Celebrating at the Source of the Nile</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The celebration continued at Source of the Nile for our after-party, where attendees, volunteers, speakers, facilitators, sponsors and organisers were welcomed to the Source of the Nile. Unbeknownst to them, there was a surprise awaiting: an after party aboard a double-decker boat. The boat ride took them on a tour of Lake Victoria and finally landed at the actual source of the Nile itself, where they learned about its history before taking time for photos together.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The Nile has been part of WordCamp Jinja’s identity across previous editions. This year, gathering there brought our theme back into focus: people with different skills and experiences had come together, learned from one another and added something to the community.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-3 is-cropped wp-block-gallery-8 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1302\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1856-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1303\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1934-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1284\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1900-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1286\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1984-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>The people who made it possible</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Jinja is built by volunteers. Long before the doors opened, the organising team was working on the venue, programme, speakers, communications, sponsorships, registration and practical activities. During the event, volunteers welcomed attendees, supported speakers, guided participants and helped the different spaces run smoothly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To our attendees, thank you for showing up ready to learn and share. To our speakers and facilitators, thank you for the time and care you put into your sessions. To the hackathon teams and contributors, thank you for building and giving back. And to every organiser and volunteer, thank you for the work people saw and the work they did not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We are also grateful to our sponsors Jetpack, Hostinger, WordPress.com, Woo, Hosting.com, SEOPress and Infinity Computers and Communications Company (i3c) and to our continued local community partners for supporting an accessible gathering for people at different stages of their WordPress journey. Their support helped bring this fifth edition to life.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-9 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1287\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1604-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Relive the weekend and keep in touch</strong></h2>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><br />You can explore photographs from the event in our WordCamp Jinja 2026 photo album:<br /><a href=\"https://photos.app.goo.gl/Fd61HxxyNT8xK4Ni7\">https://photos.app.goo.gl/Fd61HxxyNT8xK4Ni7</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp may be over, but the learning continues. The Jinja WordPress Meetup will keep bringing people together to share skills, contribute to WordPress and build on the projects and relationships started here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you for embracing the creative currents with us. See you at the next WordPress Jinja event!</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 15 Oct 2026 19:54:36 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Joan Namunina\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.20 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=250329\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/10/bbpress-2-6-20-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2031:\"<p class=\"wp-block-paragraph\">bbPress 2.6.20 is a security and maintenance release. Everyone running bbPress should update. <img alt=\"🔒\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f512.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">This release strengthens topic and reply password validation and keeps bbPress post shortcodes literal in ordinary WordPress content loops. It also adds a site-wide Forum Status setting with Open, Closed, and Frozen modes. Existing sites remain Open unless that setting is changed.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The maintenance work improves BuddyPress profile actions, group topic routes, activity visibility, and group-forum access. It also restores compatibility for subscription links in third-party theme packages, preserves moderation forms after validation errors, and includes fixes for notifications, converters, widgets, profiles, topic and reply administration, and restricted-content visibility.</p>\n\n\n\n<p class=\"wp-block-paragraph\">bbPress 2.6.20 still requires WordPress 6.0 or newer and PHP 7.2 or newer, and is tested through WordPress 7.1. The database version remains 264, so no database upgrade is required. The <a href=\"https://codex.bbpress.org/releases/bbpress-2-6-20/\">2.6.20 upgrade notes</a> cover compatibility details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These changes are also in the 2.7 development branch, which remains 2.7.0-alpha-4. Thank you to ahillmortons, alejandroescobar89, bor0, bradleyt, chefranov, dd32, deborah86, Dermes, diegootgs, dilip2615, fraph24, hardel, imath, immeet94, iworks, jgasba, josephscott, konnektiv, lmstearn, mehrazmorshed, michael8888, mike80222, obenland, Palagrin, peopleinside, r-a-y, robin-w, SirLouen, tobifjellner, wpturk, and zaerl for reports, patches, testing, and review.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.20.zip\">Download bbPress 2.6.20</a> from WordPress.org, or update from your WordPress dashboard.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 15 Oct 2026 17:46:04 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:77:\"Open Channels FM: The Hidden Dependency Problem in Open Source Infrastructure\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563681\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://openchannels.fm/the-hidden-dependency-problem-in-open-source-infrastructure/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:352:\"When we think about what keeps the Internet humming, most of us imagine massive data centers and super-fast connections. Fewer people realize that our everyday digital experiences often depend on the efforts of a very small group of individuals. Recent analysis revealed that in many essential open source projects, just one or two people are [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 15 Oct 2026 15:30:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"Open Channels FM: Rethinking Access and Dependence in Tech From AI Outages to Open Source Lifelines\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563581\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:106:\"https://openchannels.fm/rethinking-access-and-dependence-in-tech-from-ai-outages-to-open-source-lifelines/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"Who maintains education AI, the backbone of software infrastructure, and a new open source document tool.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 14 Oct 2026 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"WPTavern: #237 – Robert Abela on WordPress Security and the Battle Against AI Threats\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209016\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"https://wptavern.com/podcast/237-robert-abela-on-wordpress-security-and-the-battle-against-ai-threats\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:55681:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, the state of WordPress security in 2026, and the battle against AI threats.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you, and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Robert Abela.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Robert has been working in IT security for 25 years, ranging from antivirus software to web security scanners, and for the past decade has been running Melapress. A company focused on WordPress security plugins, particularly around user visibility, authentication, activity logs, and 2FA.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Robert is here to talk about the 2026 WordPress security survey. This is an annual project now in its fourth, or fifth, year gathering data from a wide range of WordPress professionals across agencies, enterprise teams, freelancers, and product owners. The conversation today is focused on the biggest security challenges and trends facing WordPress users in 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We start off with some sobering stats. Over 67% of survey respondents reported experiencing at least one security incident in the past year, and concerns about WordPress security remain high, especially among less technical users.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We chat about the disconnect between awareness of security threats and actually taking steps to mitigate them, such as breach recovery plans and team training.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion also explored the different types of risks that worry site owners. Site downtime, defacement, reputational damage, data loss, and even legal compliance issues. How the shakeout depends on the type of site, whether it&#8217;s e-commerce membership, a news outlet, or a simple brochure site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also talk about the tendency for even experienced WordPress users to take a reactive approach, only addressing vulnerabilities after something has gone wrong.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end of the episode, we discuss the rising impact of a AI on security, the explosion of AI facilitated vulnerabilities, and the shifting landscape of risk and response. There&#8217;s a healthy dose of reality, some optimism about the tools and best practises available, and plenty of good advice, especially for smaller teams and freelancers who may not have access to enterprise level resources.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you care about keeping your WordPress sites secure, or want to understand where the community&#8217;s biggest concerns and opportunities are in 2026, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Robert Abela.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Robert Abela. Hello, Robert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:48] <strong>Robert Abela:</strong> Hello Nathan. Thanks for having me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:50] <strong>Nathan Wrigley:</strong> You&#8217;re very welcome. Nice to have you with us.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re going to chat today about internet security, but we&#8217;re going to be looking back over the past year, so the year 2026. Robert, can tell us a little bit about the company he founded, works for, and so on. It&#8217;s called Melapress, you can find out about that in just a moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I would like to draw your attention to something which is going to really be the fulcrum of what we talk about. It is their 2026 WordPress Security Survey. Now, the easiest way to get that is probably to go to wptavern.com, search for the episode with Robert in it, and I will make sure it is linked in the show notes there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it might be a good idea to read it, because in about 10 minutes, you&#8217;re going to be able to capture absolutely everything that we&#8217;re talking about today, and you&#8217;ll get all of the data and, what have you. But that&#8217;s going to be the point of this episode, summarizing what happened in the security space in WordPress in 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Robert, I guess there are a few areas in the WordPress space where it&#8217;s pretty important to know that we know, that you know, what you&#8217;re talking about when it comes to security, because we don&#8217;t want to have a lot of hot air from somebody who&#8217;s not experienced. So it&#8217;s an opportunity for you really to give us your bio and tell us a little bit about what you&#8217;ve been doing in the WordPress space, particularly around security, the companies you&#8217;ve worked for, the things that you&#8217;ve founded and so on. So over to you, Robert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:07] <strong>Robert Abela:</strong> Thanks. I&#8217;ve been working in IT security for twenty-five years. I&#8217;ve always worked for software companies, software startups which worked in security industry. We used to do antivirus software, web security scanners, et cetera. I&#8217;ve had different positions. I started as systems engineer, QA, product management, project management, almost any field.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Anyway, and the last ten years I founded Melapress, and it&#8217;s a WordPress plugin business, and basically we develop a number of security plugins for WordPress. The security we do, we don&#8217;t do the typical firewall malware, et cetera, like the other, brands. We mostly focus on user visibility and authentication. So basically we have an activity logs plugin, and we also have a plugin for 2FA, passkeys et cetera. So we are focusing much more, on what happens post login once someone logs into WordPress, rather than the whole hardening and protection.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:56] <strong>Nathan Wrigley:</strong> Thank you for that. So anybody that&#8217;s interested, anything that we mention today, including the URLs of the companies that Robert has just mentioned, so Melapress, you&#8217;ll be able to find those in the show notes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the 2026 WordPress Security Survey, how many times have you actually run this? So obviously we&#8217;re looking at the 2026 version. Have you done this a couple of times and refined the way that you&#8217;ve done it and the way that you&#8217;ve surveyed over many years?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:21] <strong>Robert Abela:</strong> Yes. I&#8217;m not sure if this is the fourth or fifth year. But yes, we do every year, we&#8217;ve had more respondents. This year, by the way, it was the highest ever with 219 respondents. We had more, but before we publish all the results, we go through the sheet. Maybe there are some duplicates. Maybe some of them are not correctly filled in, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But yeah, we&#8217;ve been doing it for around four years, and we&#8217;ve also fine-tuned from where we gather the data. For example, the first year, we&#8217;re only sending our newsletter basically, but this year we&#8217;ve done a lot. We&#8217;ve promoted the survey through third parties. We&#8217;ve gathered responses from WordCamp Europe, in person, through a number of other conferences, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So while there is still a percentage that most probably are our users or our clients, still the biggest percentages is spread out to a wide range of different type of WordPress users, ranging from people who work for agencies, developers, designers, but also people who work with WordPress in bigger enterprises or businesses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:15] <strong>Nathan Wrigley:</strong> Okay, so yeah, caveat emptor. With that in mind, the limitations, or otherwise, of the numbers that you&#8217;ve got represents what you&#8217;ve got in this survey.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And essentially, what it boils down to is a, it was kind of a bunch of questions which then led to a bunch of information being spat out the other side. And I&#8217;ve summarized it into about 10 bullet points. It may very well be that I&#8217;ve missed a few bits and pieces, but be interesting to go through, and you can lend your experience as to whether or not there&#8217;s been any change, whether things have got worse, whether things seemingly have got better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;ll begin, if it&#8217;s okay with you, with the top item, which I suppose, came out, which was a concern around WordPress&#8217;s security, or the things that can happen around WordPress and security. And what came out of it was that 7.85 out of 10, so 78 and a half percent, I suppose you could describe it as. They were developers who were expressing basically that they were concerned.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, I don&#8217;t know if you have more telemetry, like what concerned means, but off the face of it, that seems like quite a high number. If the platform that you&#8217;re using to build websites, you are in the sort of mid-70s concerned, is there anything you wanted to add to that or is that just the sort of top level statistic?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:28] <strong>Robert Abela:</strong> No. That was like a top-level statistic, a question we ask, like if people are concerned or they have worries about their WordPress, the security of their website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What&#8217;s funny is the last few years, the level of concern has been the same. However, also we&#8217;ve noticed that people who have some sort of recovery plan, et cetera, also remains the same. So the level of concern has remained the same. So the majority of people know that something can happen to their WordPress website, especially now with AI, et cetera. It&#8217;s even more, things are moving much faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\">However, it seems like people are not taking the next step, as in like taking action to make sure nothing happens. What I&#8217;ve noticed as well, once we break down those who have concerns and what job they have, if they&#8217;re developers, or with their security people, et cetera. There&#8217;s this correlation, like, the more informed someone is, the more is involved in the tech aspect of the website, the more understanding they have on how things work, the less concerned they are.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So maybe it could also be education or awareness because of course, if you don&#8217;t know about how something works, then of course you are much more concerned. How you&#8217;re going to protect it? However, if you are, let&#8217;s say, a developer and has an understanding of sessions, cookies, the usual things, like passwords, maybe you&#8217;re a bit less concerned because you feel you are a bit more in control of how you can protect your website and what you can do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:39] <strong>Nathan Wrigley:</strong> It seems like on the face of it, I should say, it seems like 78%. It seems like quite a lot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:44] <strong>Robert Abela:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:45] <strong>Nathan Wrigley:</strong> If I had any kind of intuition, let&#8217;s say I was to go out into my car and drive around the street, if I thought that 78% of the time there was going to be some potential accident. Or I was worrying of the time about the possibility of an accident, I don&#8217;t think I&#8217;d be getting in the car. So it&#8217;s kinda curious. But, let&#8217;s move on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the next data point that dropped out was 67.7%, so let&#8217;s call it 68% of respondents. Now this is fairly shocking, and maybe this number will actually start driving up in the years to come, and we can get into that later.</p>\n\n\n\n<p class=\"wp-block-paragraph\">68% of respondents had experienced at least one known security incident, with many multiple incidents. Now, that really is shocking to me. Closing in on 70% of people have had some kind of incident. I don&#8217;t know what, or maybe you do, what the magnitude of that is, but did that surprise you? Did that seem like a really large number?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:38] <strong>Robert Abela:</strong> 67.7 of all respondents, correct, they reported one security incident. I&#8217;m not surprised because almost everyone I speak to at WordCamps, even non-WordCamps, other events, someone down the line has had some security issue. Not just with WordPress, but especially with WordPress. And the funny thing, it&#8217;s not even funny, but 13.2% of those are repeat targets, which means they have experienced more than five security incidents.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, why does it happen? There are a number of reasons. Outdated software, lack of user awareness. In fact, what&#8217;s really more concerning is, I have some numbers here actually I can tell you. Yes, we&#8217;re still looking at some other statistics. Only 27.9% reported like they have some sort of training for their users. And only 37% use logs. At least 2FA&#8217;s a bit higher, it&#8217;s around the 40% something. I don&#8217;t have the exact number right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, so I&#8217;m not surprised because there is still a lot that can be done from website owners, from agencies, from everyone, to make sure we take down that number, and not everyone. Or so not the majority of people experience some sort of security incident on their website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:41] <strong>Nathan Wrigley:</strong> Yeah, it&#8217;s curious. It&#8217;s not really a conversation. When I&#8217;m at events or chatting to fellow WordPressers, security is not the default conversation that I have, because I&#8217;m not a security person. So I end up chatting about, I don&#8217;t know, custom post types and how to do various things that I&#8217;m doing. Maybe podcasting in the WordPress space or something along those lines.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You, I guess, are having these conversations, and it&#8217;s very much in the territory. It&#8217;s in your wheelhouse. And so maybe it&#8217;s not a surprise to you that 67-plus percent of people have had something in the last year. But, on the face of it, that just seemed like so many. If I see 1,000 people at a WordCamp and I think, &#8220;Well, 670 of those have had a problem during the course of this year,&#8221; gosh that really does seem like a systemic problem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I know that outside of the WordPress community, WordPress gets a bit of a hard rap, on the security front. It&#8217;s insecure and what have you, and, all of the caveats. We know that really isn&#8217;t typically the case for WordPress Core. Tends to be the addition of code and plugins and themes that adds that on top. But I&#8217;m still surprised, feels almost like if the mainstream press got hold of your survey and just pull out that one statistic and bandy it around, it doesn&#8217;t feel great, if you know what I mean.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:53] <strong>Robert Abela:</strong> Yes. I think WordPress gets a lot of bad rep also because it&#8217;s very popular. As in like pre-WordPress, I&#8217;ve used web servers before as in like custom PHP websites, .NET, IIS, Apache, et cetera. Websites used to get hacked as well in the thousands. The thing is that you couldn&#8217;t point your finger to one type of website, you know because they were all custom. So these problems have been happening since we started having websites, quite frankly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">With WordPress, unfortunately it happens and we have a bad rep because I think there are two things. Look, first of all, it&#8217;s very popular, so it&#8217;s always there. If WordPress power is around 42, 43% of the, or maybe it went a bit down, but anyway, let&#8217;s say 40%.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:30] <strong>Nathan Wrigley:</strong> Roughly, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:32] <strong>Robert Abela:</strong> Yeah, The chances, for every 10 websites, four of them are going to be WordPress. That&#8217;s a common denominator. So of course, WordPress is going to get a lot of attention.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I also think, again, goes hand in hand with how many people have security concerns. WordPress has made it very easy to launch your own website, which is a good thing. However, of course, those same people who launch their own website, maybe they don&#8217;t have the technical understanding and experience what it takes. Because setting up a website&#8217;s one thing, but keeping, managing a website for a year, two, three, and growing it, adding new functionality is another thing. So most people might not have the experience that they have, so of course, it&#8217;s much easier to find security issues with these type of websites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:10] <strong>Nathan Wrigley:</strong> Okay, we&#8217;ll move on anyway. So we&#8217;ll talk about the concerns. So you&#8217;ve obviously polled your recipients of the survey about the kind of things that they were worried about. So what are the outcomes that they fear the most, if you like?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And website availability, so the taking down of a website came in at number one, with 55.8. And then in no particular order, but these are the two that I picked out. The fear of being defaced, so the website in some way being amended, or there being some reputational damage because of what the amendment was. I don&#8217;t know, maybe there was some imagery, or some slightly political content that ended up on your website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That was just slightly south of the availability, so that was 54.2%. And then dropping a full 10%, so 46.4%, was the worry about data theft or loss. Frankly, I&#8217;m not surprised by that. I guess any developer&#8217;s nightmare is their website actually disappearing off the internet. That&#8217;s number one, so that doesn&#8217;t surprise me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I remember in the day, 15 years ago, defacement was the thing. Honestly, I can&#8217;t say that I&#8217;ve been browsing the internet recently and seen something that&#8217;s been defaced. It seems like the hackers have all moved on. Maybe there&#8217;s things buried in the source code that I don&#8217;t know about.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, it doesn&#8217;t surprise me that the availability is the main thing. But I am surprised that data loss comes in third, if you like. I personally would have had that as number one, especially, if you&#8217;ve got a, I don&#8217;t know, an LMS, or you&#8217;re connecting with a CRM, or you&#8217;ve got form data which potentially is capturing something personal that the GDPR would worry about. So there&#8217;s no question, just if you want to comment on those particular things, go for it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:42] <strong>Robert Abela:</strong> No, definitely. Those are the numbers based on all the respondents. But if you start breaking down the numbers, there&#8217;s more nuance to, to these things. So for example, if you look, those who are concerned about website availability, or defacement, are usually those who have content websites. Mostly based on content, news, magazines, et cetera. Those who are more concerned about financial loss or data theft are more the e-commerce websites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:08] <strong>Nathan Wrigley:</strong> Oh that makes sense. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:09] <strong>Robert Abela:</strong> The membership websites, et cetera. In fact, the membership websites are as well more concerned, for example, about compliance because of privacy. So those numbers, like fifty-five point eight percent, those are from the all respondents. But as soon as you break all that down, it differs a bit on the type of website you have.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s expected because if you have an e-commerce website, of course you are dealing with billing details, payments, and all this stuff. If you have a membership website, maybe you are also dealing with payment details, but you are also dealing with much more data. Maybe you have some sort of internal chat. People are sharing their addresses on it, their personal information. So that you are more concerned about GDPR or any sort of compliance, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if your main selling point is if you have a content website, a news website, and your main selling point is your website being available, then of course that is your biggest worry.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:53] <strong>Nathan Wrigley:</strong> That&#8217;s an interesting split of the data there. That makes perfect sense, of course, now that you say it in that way it really is obvious.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that was you polling your respondants respondents there, and you were trying to figure out what their worries were and what they were into and all of that kind of stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then we sort of to move to a different realm where despite all of that being said, so, you know, got a lot of people worried. We&#8217;ve outlined some of the different worries that they have, depending on the type of website that they&#8217;ve got.</p>\n\n\n\n<p class=\"wp-block-paragraph\">From all of that, if you&#8217;d have ended the survey there, I would have assumed at that point that everybody had something in the back pocket to pull out, an SOP or something like that, to pull out in the event of an actual problem. If data theft is apparent, we do this. If the website goes down, we do this. But your survey reveals entirely the opposite.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the high numbers on the one side, the fear numbers, are not mirrored by the what we&#8217;re going to do about it numbers, because you go straight into the high 20s, so 27.9% had a breach recovery plan. So how to get back from a problem with your website being, let&#8217;s say, hacked, let&#8217;s use that word. And 26% provided some sort of training for their team, some sort of security team training, that kind of thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Again, does that surprise you? You&#8217;re in this space. Maybe that&#8217;s really typical, but given the high levels of concern, there seems to be a real disconnect with what we&#8217;re going to do about it. That&#8217;s curious.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:18] <strong>Robert Abela:</strong> I&#8217;m not surprised, in the sense, it&#8217;s very common. The majority of people, especially nowadays, there&#8217;s much more knowledge that, yes, websites can be hacked, this can happen. However, that doesn&#8217;t translate. People don&#8217;t have the, I don&#8217;t know if it&#8217;s the resources, the means, the time to actually take action on it, to prepare some things. So, I&#8217;m not surprised.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Again, similar to what we discussed before, there&#8217;s a bit more nuance to these type of numbers because you said only 27.9% has a breach recovery plan. Actually, that&#8217;s based on all the respondents, but typically the number is much less, because when you look at it, from the respondents, from all those who have a security breach, from those 27.2%, 70.2% which have control in place are corporate or brand websites, which means they have their own in-house team. Only those, 70% of those have their own, have their activity logs, have their firewalls in place, have a recovery plan in place, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the number of, let&#8217;s say, the non-branded, the smaller websites, yeah, they have absolutely nothing. They have no sort of recovery plan or anything like that. In fact, the numbers are much smaller. Only 23% of those websites typically have some sort of recovery plan.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:23] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:24] <strong>Robert Abela:</strong> I&#8217;m not surprised because usually, especially if you&#8217;re an enterprise, or a bigger business, you are bound by more compliance. Maybe you have more security people on board who are much more aware what can happen of what they need to do. But yeah, the average website doesn&#8217;t have these things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:38] <strong>Nathan Wrigley:</strong> Yeah. I wonder if your data here might be skewed by the type of correspondent that you got. So for example, who knows how many blue-chip companies, have submitted to your information gathering here. Perhaps not many, but maybe you got lots of WordPress community members, and so the data might be skewed in that direction. But that&#8217;s an interesting point. So dependent upon the nature of the website and the type of team they have behind it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it is still, regardless of all of that, it is still quite low. And I was using my analogy earlier about insurance, and I think that applies here. Insurance is the most uninteresting thing to purchase because you spend this money and, let&#8217;s say for example, you got home insurance. I would imagine most people typically go through a year and they never make use of it. Sorry to anybody listening who has obviously had to make use of that. But the moment you need it is the moment that you&#8217;re glad of every single penny that you&#8217;ve sunk into that, and I guess that applies here. If we can persuade people to get that data breach recovery plan, whatever it may be, have that in your back pocket, that would be a useful thing to have.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:38] <strong>Robert Abela:</strong> Yeah. As I&#8217;ve said in the beginning, I&#8217;ve been working in IT security companies, security software companies for 25 years. All of them, the most common sales opening, like sales reason, like people coming to us like, &#8220;Hey, this happened, so now I need this.&#8221; They&#8217;re always after they&#8217;ve been hacked, after they&#8217;ve been a leakage, after there&#8217;s been something wrong.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Very few proactively come and as I said, like the bigger enterprise companies, because they have certain regulations and stuff and certain budgets that they invest in these things. But the average website, yes, first they have to experience something, and then. I think it&#8217;s, in all fairness, I think it&#8217;s common human nature. It&#8217;s not just about IT. We tend to be all humans. We tend to be like, &#8220;Oh, we&#8217;ll see later,&#8221; and then if it happens, &#8220;Ooh, I should have&#8230;&#8221; it&#8217;s always like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:17] <strong>Nathan Wrigley:</strong> Well, there&#8217;s also that calculus of how much time does it take to recover. So for example, if you&#8217;ve got a brochure site, and you&#8217;ve got backups going back for many many months you can restore to a point that you&#8217;re fairly sure that everything was actually fine, and the breach has been mitigated by going backwards in time. But it&#8217;s just all the wasted time. It&#8217;s the wasted time going through the backups and seeing, okay, is this backup, does it have the malware in as well? Okay, that one does. What about this one? What about this one?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And there&#8217;s no knowing how long that&#8217;s going to be, and the minute you step, as you said, into e-commerce and you&#8217;ve got transactions happening every couple of minutes, and then you&#8217;ve got receipts and you&#8217;ve got to fulfill those orders, and somehow, oh boy, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:59] <strong>Robert Abela:</strong> Yes. Then it&#8217;s a different ballgame. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:02] <strong>Nathan Wrigley:</strong> Different ballgame isn&#8217;t it? Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, so the next point that we&#8217;re going to move on to is actually one that you probably just made. And it&#8217;s that the detection in most cases, well actually not most cases, in many cases. So 42.6% of your respondents said that their detection is mostly retroactive. So that is to say the thing has already gone wrong. Somebody in the 42.6% of the case is because they see something on the website. They&#8217;ve noticed that something isn&#8217;t quite right, something looks out of order.</p>\n\n\n\n<p class=\"wp-block-paragraph\">38.4% because they were actually inspecting the logs. That tells me that whoever&#8217;s inspecting the logs is doing diligent work. That&#8217;s kind of interesting. So don&#8217;t know if you want to comment on that, but basically a lot of people are figuring this stuff out after the thing has happened, as you described, not before the thing has happened.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:51] <strong>Robert Abela:</strong> Yes. So there are four criteria. So 42.6%, as you said, is common website behavior, either detected by their team or by clients. 38.4 via logs. Now, the logs is a bit, it can be reactive and proactive, because with the logs, you can actually, in fact, we have some notes on this, but I don&#8217;t have the exact numbers right now. Because some of them were actually by someone analyzing the logs, but some of them were actually because someone has configured notifications based on the logs, like a sort of intrusion detection system.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so if, I don&#8217;t know, if X login happens after X time, whatever, please send me an email or an SMS, and that, it&#8217;s still reactive in a way, but at least they could act right away as soon as it&#8217;s happening. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:31] <strong>Nathan Wrigley:</strong> Yeah kind of proactive reactive, isn&#8217;t it? That&#8217;s a really interesting subcatagory.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:33] <strong>Robert Abela:</strong> Exactly, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:34] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:34] <strong>Robert Abela:</strong> So yeah, but yeah, it&#8217;s still reactive because then you have 35.6% they knew through their web host, and 30% they knew through some sort of malware scanner alerts on their website, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:45] <strong>Nathan Wrigley:</strong> Okay. Again, just kind of interesting data coming out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the next one, incidents most commonly resulted in downtime for the website. So that&#8217;s pushing up to 70%, 68.4% of whatever happened, resulted in some downtime. And then I don&#8217;t have the numbers for the following data, but I guess it decreases from here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The next thing was reputational damage. That was a result of some sort of incident. And then search engine ranking is affected. That&#8217;s an interesting byproduct.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This one&#8217;s brutal. Client trust disappearing. That&#8217;s really interesting. And then in some cases, lost revenue. I imagine the lost revenue is being described as in some cases, because, as we described earlier, if you&#8217;re dealing with revenue, you&#8217;ve probably got more bulletproof security measures in place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the ones that sort of jump out to me there aren&#8217;t the downtime, because I would&#8217;ve assumed that. It&#8217;s really the curious byproducts of things like the reputational damage, the search engine damage. You can&#8217;t really get your hands on those, can you? There&#8217;s no real way of knowing what that&#8217;s going to look like or feel like, or how that&#8217;s going to affect your business this year or next year.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just to know that, you wake up one morning to discover that you were in first place on Google after six years of hard SEO work, only to discover that you&#8217;re now in fourth and descending fast, that&#8217;s pretty brutal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:01] <strong>Robert Abela:</strong> Yes. And in fact, if you break down those numbers a bit more, like 45.9%, there&#8217;s loss of search engine ranking, and that happens usually when search engines detect you have issues. I don&#8217;t know if you remember, Google used to have that page sometimes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that happens. When that happens, when the search engine themselves realise there&#8217;s an issue, you lose a lot of rank. The penalty you get there is very heavy. In fact, only 14.5 of those who have had some issues with the website has lost ranking because they have discovered their issues before the search engine did.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So again, that&#8217;s why you should be a bit more proactive because if your search engine finds out before you, the penalty, as you said, and you cannot really quantify it because God knows how long you will remain. As you said, if you were position one for six years in a row, now one fine day you&#8217;re on the second page, God knows how much work you need to go back up, and you cannot even calculate what the revenue loss is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But when it comes to revenue loss, again, it&#8217;s the same. There are some websites, I&#8217;ve seen some websites where like they generate $70,000 per hour. So for every hour down, that&#8217;s $70,000 gone.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, there are lots, and of course, the reputation, on top of the reputation, there&#8217;s also compliance and legal consequences, especially in the US. Things are becoming much stricter now. If you had some issue, some customer data has been leaked, you have problems with the law, fines, and other similar stuff. So, the financial damage to all of this, of your website getting hacked, is very high.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Not just the reputation, losing customers, you might end up in court. You might lose your search engine ranking, and that is why most probably it&#8217;s a good idea to become a bit more proactive rather than reactive. Or it&#8217;s almost impossible to, there is no 100% secure solution, and that is why I think it&#8217;s very important to have good hardening, but also good monitoring, the whole process, the whole 360 degrees, the whole cycle.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:44] <strong>Nathan Wrigley:</strong> It&#8217;s such a curious industry that you&#8217;re in because, how to describe this? It would seem, or at least, it would be possible to perceive that this security survey is perfectly aligned with your business goals in a way. There&#8217;s loads of problems out there on the internet. There&#8217;s multitudes of ways that things can go wrong, and for every one of them, there&#8217;s, a WordPress solution out there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I know Robert. We&#8217;ve met many times before. I get the intuition that&#8217;s really not why you&#8217;re doing this, although somebody listening to this might have that sort of slightly, I don&#8217;t know, cynical approach that, Robert&#8217;s just saying this so that he can launch his Melapress products at you. Just put our minds to rest on that score. Why do you actually carry out this survey?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:25] <strong>Robert Abela:</strong> Good question. Actually, our plugins only address part of the security. There&#8217;s much more when it comes to firewalls, et cetera, that I still say hardening you still need. We don&#8217;t even cover it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">No, we do it, honestly, it started around four or five years ago, for me, it was just curiosity. It sounded like an interesting to do. Hey, let&#8217;s do a survey, just experimenting, et cetera. And we had very good response, and now we&#8217;re just, doing it honestly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Like I really believe that by knowing, this is not just about WordPress security, about everything else. By knowing where other people are doing it wrong, you will learn from it. By knowing, okay, clearly I can see, for example, as we were saying, like seventy percent, seventy point two percent of enterprise and marked businesses usually have logs, usually have firewalls, et cetera. Maybe we should aspire more towards them and be more like the average website should have a bit more like things like that, and maybe they&#8217;re doing something right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yes, there is a lot to learn from surveys in general, not just this, any type of survey. There is usually a lot to learn. And that&#8217;s why we&#8217;re doing it as well, because from the first time we&#8217;ve done it, which started really as a curiosity project, we got so much good feedback. And actually the second year people were asking us if we are going to do it. Because yeah, people learn from these things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I mean, of course there&#8217;s the benefit of it, hopefully it will promote as well a bit our plugins. But anyway, it&#8217;s going to promote all other type of security solutions. We are not, in fact, the survey is not tailored just for our plugin. It talks about everything. As I said, the whole security cycle. You have the hardening, you have the monitoring, updating, et cetera, and we only do one part of it, the monitoring aspect, basically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:50] <strong>Nathan Wrigley:</strong> Before we move on to our sort of final bit, which I want to concentrate on AI, I&#8217;m just going to wrap up the security bit just by summarizing what comes towards the end. And it&#8217;s less about numbers, and it&#8217;s more about just conclusions that may have been drawn. But most of it, I think, would be fairly obvious from what we said. So I&#8217;ll just summarize it a little bit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The first one is that e-commerce and membership sites tend to have greater security concerns and stronger practices. That kind of makes sense. I guess it reflects the nature of the business they&#8217;re in, and the kind of data that they&#8217;re holding, and the legal compliance that they may need to be concerend with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In-house teams are more likely to have recovery plans. Again, I presume that&#8217;s fairly obvious. The boss, the head of the pyramid can sit down and say, &#8220;Okay, it&#8217;s your job now to crack on and do that. You&#8217;ve got a week to figure out all this sort of stuff,&#8221; and what have you. Whereas a freelancer sitting in their own office, there&#8217;s always regular work to be built, sites to be built and other things to do. So I can well imagine why that&#8217;s the case.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And sites, again, fairly obvious, sites with repeated security incidents tended to have stronger controls in place. Today, presumably, it&#8217;s a case of once bitten and all of that. Once you&#8217;ve actually had this nasty stuff happen to you, you&#8217;re pretty likely to make sure that does not happen again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In summary, I suppose the reports really, the recommendations are focus on prevention, detection, and recovery rather than simply adding in more security tools, would be the way that I would describe it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, let&#8217;s move on then just before we finish. It is, as we&#8217;re recording this, it&#8217;s September 2026. In the more recent past, I want to say, I don&#8217;t know, the last two months, something like that, the WordPress security news bulletins have been on red alert really. We&#8217;ve had some charts being put out on social media which show the amount of vulnerabilities discovered, and also the amount of AI-based plugins that have gone into the repository. The supply chain attacks that have suddenly become a thing. A lot of it really because people can corral AI to do mischievous stuff and what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t really have a question, but I just wondered if you had a comment on where we are in September 2026, because it does feel as if there&#8217;s quite a lot of, there&#8217;s a lot of scope to be very doomer at the moment. It almost feels like the AI is winning the arms race, but maybe that&#8217;s not what you&#8217;re thinking from your end.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:04] <strong>Robert Abela:</strong> No, it looks a bit negative. I wouldn&#8217;t say AI is winning the race. Actually, people with malicious intent using AI are winning because AI is neutral in a way, like it depends on what people ask the AI to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:15] <strong>Nathan Wrigley:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:16] <strong>Robert Abela:</strong> But it is worrying, yes. The graph you are mentioning, I saw a graph shared by John Blackbourn, yeah, about the number of issues reported in the HackerOne WordPress vulnerability program, which is insane.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:28] <strong>Nathan Wrigley:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:29] <strong>Robert Abela:</strong> And they received more reports in the last week than they ever did in a whole number of months. So yes, it is worrying. You can look at it both ways. The same way attackers can use AI to find issues. We are doing it ourselves as well, quite frankly, because whenever there&#8217;s a new model out there from all of these vendors, most probably attackers are going to use them to scan our code, et cetera. So we&#8217;re doing it as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We always used to do the manual security analysis, et cetera, but now that we have AI, with every release, we just hammer the update and try to find as many issues as we can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The reality is also that some, if not many of these vulnerabilities are not actually so easy to exploit. Like it&#8217;s really, the stars really have to align and it&#8217;s really, but still, it&#8217;s better safe than sorry. Because even though today it might be difficult to exploit a particular issue, in six months&#8217; time, we might have technology that might make it very easy to exploit this type of issue.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It looks negative, but the same tools that attackers have, malicious users have, we have them as well. So it&#8217;s up to us to use them and be ahead of the curve, and use them proactively ourselves and before every update, during the whole development cycle. We should use them more often to make sure at least that we cover what other people can find before us.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:35] <strong>Nathan Wrigley:</strong> Yeah. I suppose the bit that I find curious is the optics of it. So, there was always this universe in which people would be able to throw dirt at WordPress because you know WordPress isn&#8217;t secure, and we talked about that earlier. It&#8217;s usually plugins and very rarely Core. Plugins, themes, additional code, what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">However, given that it would appear that people can stack 14 overlapping problems and create this one vulnerability from things that probably humans would never have conceived in the past. That then just lends into this narrative of, well there&#8217;s this deluge, this tidal wave of things that are coming at WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I woke up this morning to discover in my feed BleepingComputer. I don&#8217;t know if you&#8217;ve seen this one yet today, but BleepingComputer have got an article with a CSV attached to it about yet another WordPress thing. And it just feels like that sort of day in, day out, there&#8217;s just another and another, and it&#8217;s that narrative that, that concerns me. It&#8217;s just that it gets away from us, that there&#8217;s one this day, there&#8217;s one this day, one this day, one this day.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And having to explain, &#8220;Look, calm down. That one was nothing. Okay, calm down. That one was also nothing. Okay, yeah, that one was something, but that one was nothing, that&#8230;&#8221; It&#8217;s just that constant fighting the narrative in an era where every day something seems to be out in the press, a problem that WordPress. Do you capture what I&#8217;m saying there?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:57] <strong>Robert Abela:</strong> Yes, no, and no wonder we get negative rep in the rest of the IT industry because, yes, we do get these news, and the numbers are very big. If you find a vulnerability in a plugin that has half a million installations, all of a sudden you see the news, &#8220;Oh, half a million WordPress websites are vulnerable to X.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">Unfortunately, yes. The thing is, WordPress in general, it&#8217;s very secure like. There are so many I&#8217;ve seen in my life, I don&#8217;t know how many custom web applications I have seen that are horrible in terms of security, like really horrible. It&#8217;s just because, of course, no one is seeing these because this might be a website in millions of websites, so no one is targeting. But WordPress, because it&#8217;s a popular platform, is going to be targeted.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But yeah, because the numbers are big, yeah, unfortunately, we do have a bad rep. And yeah, the news like to sensationalize things as well. So yeah, the rep is not good, no. But the reality is that it&#8217;s going to happen. It&#8217;s going to happen more often, most probably. It happened to us. All the vendors I&#8217;ve spoken to at WordCamp US and WordCamp Europe, they&#8217;re all the same. If you look at our plugins as well, maybe we used to get, I don&#8217;t know, maybe on average a vulnerability or two reported a year.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As soon as this whole AI started thing, all of a sudden within a month or two, you get like four, five, six reports like, &#8220;Whoa, what happened?&#8221; In just one week. It&#8217;s just reality. It&#8217;s up to us, as I say, we have to be more proactive. Of course, it&#8217;s easier said than done, but we have to be more proactive and try to use the same tools that attackers are using to make sure at least we detect them, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:13] <strong>Nathan Wrigley:</strong> Yeah, the bit that genuinely I find curious is what will be the calculus in terms of time that people can spend on this stuff. So as an example, if let&#8217;s say that by January 2027, many of us are having to spend a good proportion of every day, and by a good proportion, I don&#8217;t know, let&#8217;s say 30 minutes or something, browsing through the news to see if anything has cropped up. Or indeed to read the things that we know has cropped up because the fire hose of security news has gone through the roof.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This seems like it could happen, that we&#8217;ll all have to be mindful of it. And it&#8217;s just that sort of attritional wear and tear that, &#8220;Okay, really? Do I have to do this each and every day?&#8221; That will be interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I suppose the flip side of that, curiously, is that it, how to describe this? It doesn&#8217;t do your business any harm because the more that people are concerned about their WordPress websites, the more security news there is, the more that they will be drawn to companies like yours. So it&#8217;s a very curious tightrope walk that you&#8217;re going to have to perform, I think as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:10] <strong>Robert Abela:</strong> Yes. Yes, it&#8217;s the reality. If I can do a shameless plug, at WordCamp US, I spoke about, WordPress user sessions and hijacking, and one of my lines was that all the things I had mentioned, but the talk is available on YouTube on the WordPress channel. All the things that I have mentioned, so many missed it, because if you look at user session hijacking, the bottom of it is all derives from user mistakes. A user making a mistake, that&#8217;s all it is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the reality is it all sounds dramatic. It all sounds like it&#8217;s the end of the world and apocalyptic. However, the reality is that, yes, nowadays, if you use a website, even as a user, you need to be aware of some basic things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yes, there are these news, and hopefully more and more people will become aware and more and more people need to become aware that yes, these are the dangers, these are like the risks of logging into a website nowadays. Of maintaining a website nowadays. It is. It&#8217;s like a double-edged sword. Like the news are making sometimes a bad rep for WordPress, but they&#8217;re also reaching more people that they need to wake up and say, &#8220;Oh, these are the risks, so we need to take action.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:07] <strong>Nathan Wrigley:</strong> Yeah, it will be interesting in the face of AI vulnerability. It&#8217;d be interesting to see what the, let&#8217;s say hosting companies, let&#8217;s paint a target there. What they do to manage their stack, because obviously it&#8217;s going to be very important for them to make sure that the clients that they have. And how they position themselves in the news, and how they can portray the security solutions they&#8217;ve got. But as well as companies like you, you know, plugins and other firewall companies and things like that. Be interesting to see through 2027 how they manage that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay. In which case we will wrap it up there. Just another quick reminder, go to the WP Tavern.com website, search for the episode with Robert Abela. You will be able to find the 2026 Melapress WordPress Security Survey over there. Download it, have a little bit of a look. And Robert, are you available anywhere online? Do you, other than Melapress&#8217; do you actually make yourself available? And if so, where can we find you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:58] <strong>Robert Abela:</strong> Yes, I&#8217;m active on LinkedIn, Robert Abela. I&#8217;m active on X.com, and I finally also have my own website. It&#8217;s more on personal things quite frankly, but yeah, it&#8217;s robertabela.me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:08] <strong>Nathan Wrigley:</strong> In which case I will bury those in the bottom of the show notes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:12] <strong>Robert Abela:</strong> Thanks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:12] <strong>Nathan Wrigley:</strong> So that you can find those. Robert Abela, thank you for chatting to me today. I really appreciate it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:16] <strong>Robert Abela:</strong> Thanks likewise.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/robertabela/\">Robert Abela</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Robert has been working in IT security for 25 years, ranging from antivirus software to web security scanners, and for the past decade has been running Melapress, a company focused on WordPress security plugins, particularly around user visibility, authentication, activity logs, and 2FA.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Robert is here to talk about the 2026 WordPress Security Survey, this is an annual project, now in its fourth or fifth year, gathering data from a wide range of WordPress professionals across agencies, enterprise teams, freelancers, and product owners. The conversation today is focused on the biggest security challenges and trends facing WordPress users in 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We start off with some sobering stats, over 67% of survey respondents reported experiencing at least one security incident in the past year, and concerns about WordPress security remain high, especially among less technical users. We chat about the disconnect between awareness of security threats and actually taking steps to mitigate them, such as breach recovery plans and team training.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion also explored the different types of risks that worry site owners, site downtime, defacement, reputational damage, data loss, and even legal compliance issues, how these shake out depends on the type of site, whether it’s e-commerce, membership, a news outlet, or a simple brochure site. </p>\n\n\n\n<p class=\"wp-block-paragraph\">We also talk about the tendency for even experienced WordPress users to take a reactive approach, only addressing vulnerabilities after something has gone wrong.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end of the episode, we discuss the rising impact of AI on security, the explosion of AI-facilitated vulnerabilities, and the shifting landscape of risk and response. There’s a healthy dose of reality, some optimism about the tools and best practices available, and plenty of good advice, especially for smaller teams and freelancers who may not have access to enterprise-level resources.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you care about keeping your WordPress sites secure, or want to understand where the community’s biggest concerns and opportunities are in 2026, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://melapress.com\">Melapress</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://melapress.com/wordpress-security-survey-2026/\">WordPress Security Statistics 2026: Melapress Survey Results</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://robertabela.me\">Robert&#8217;s personal site</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 14 Oct 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:22:\"Matt: RIP Eric Binnion\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155218\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://ma.tt/2026/10/rip-eric/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3484:\"<p class=\"wp-block-paragraph\">For the next 30 days, a few billion of you will get an extra header in honor of <a href=\"https://eric.blog/\">Eric Binnion</a>. The code in Nginx to do this is poetic:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\"><code>add_header X-Remembering \"Eric Binnion &lt;<a href=\"https://friendsofericbinnion.wordpress.com/\" rel=\"noopener\" target=\"_blank\">https://friendsofericbinnion.wordpress.com/</a>&gt;\" always;</code></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Our design team will make that less AI and more humane in the coming days. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://automattic.com/\">Automattic.com</a> will have a mourning band for 30 days. </p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-155223\" height=\"150\" src=\"https://i0.wp.com/ma.tt/files/2026/10/image.png?resize=570%2C150&#038;quality=80&#038;ssl=1\" width=\"570\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Eric was the 21<sup>st</sup> recipient of the Distinguished Janitor Award, Automattic&#8217;s highest honor, and in our hangs the last few months we&#8217;ve been talking about how to redefine and evolve it, which will happen internally at Automattic. One of the ideas was for the award to come with a physical memento, an etched tungsten cube. I don&#8217;t have many words so I&#8217;ll share something I wrote to Eric a few months ago when I gave him my cube when he was going through chemo.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Two Totems To Take With You</p>\n\n\n\n<p class=\"wp-block-paragraph\">The first is a tungsten cube I keep on my desk. Its weight will surprise you, but tungsten is singular in having the highest melting point of any metal. That represents one of the things I admire most about you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tungsten has an atomic number of 74, its symbol is W, and it’s also known as wolfram.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">My next post I&#8217;ve had in drafts for a while so please try to imagine me happy and promotional when reading it, but otherwise, I&#8217;m wrecked. Just going to soldier through because that&#8217;s what Eric always did.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-155226\" height=\"403\" src=\"https://i0.wp.com/ma.tt/files/2026/10/MCM_0869-1024x683.jpg?resize=604%2C403&#038;quality=89&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Other Automattician posts:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Jesse Friedman: <a href=\"https://jesse.blog/essays/the-loss-of-a-giant-part-one/\">The Loss of a Giant — Part One of Two</a>.</li>\n\n\n\n<li>Matías Ventura: <a href=\"https://matiasventura.com/post/remembering-eric/\">Remembering Eric</a>, with a Walt Whitman poem.</li>\n\n\n\n<li>Beau Lebens: <a href=\"https://beau.blog/2026/10/remembering-eric/\">Remembering Eric</a>, &#8220;I was lucky enough to be his first team lead&#8230;.&#8221;</li>\n\n\n\n<li>Rémi Corson: <a href=\"https://remicorson.com/articles/2026/10/bon-voyage-eric\">Bon Voyage, Eric</a>, &#8220;We got tattoos together.&#8221;</li>\n\n\n\n<li>Job Thomas: <a href=\"https://job.blog/2026/10/14/remembering-eric/\">Remembering Eric</a>.</li>\n\n\n\n<li><a href=\"https://friendsofericbinnion.wordpress.com/\">Big Legacy of Eric Binnion tribute site</a>.</li>\n</ul>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 14 Oct 2026 06:53:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:17;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"OpenStation Blog: I Deleted 168,000 Lines of Comments. My AI Agent Didn’t Notice\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1474\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:96:\"https://openstation.blog/2026/10/13/i-deleted-168000-lines-of-comments-my-ai-agent-didnt-notice/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7674:\"<p class=\"wp-block-paragraph\">Almost a third of our source code was comments. I deleted all of them and asked an AI agent to build the same features on both versions of the codebase, three times each. The code it wrote was just as good with or without comments.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you use agents on a real codebase and wonder whether comments help them, slow them down, or don&#8217;t matter, here&#8217;s what I found.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why I tried this</h2>\n\n\n\n<p class=\"wp-block-paragraph\">In <a href=\"https://x.com/poteto/status/2102050467505430555\">this video</a> (around 23:07), <a href=\"https://x.com/poteto\">Lauren</a> mentions that they don&#8217;t let their agents write comments in the code. <a href=\"https://github.com/wordPress/openstation\">Our codebase</a>, is the opposite: it&#8217;s full of comments, and most of them were written by agents.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I wondered: are all those comments helping the agent, or are they just extra text it has to read?</p>\n\n\n\n<h2 class=\"wp-block-heading\">The experiment in one paragraph</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I made a copy of the codebase with every comment removed, about 168,000 lines in total. Then I gave the same task to the same agent on both copies, three times on each, and checked the results the same way. I did this for two tasks, a small one and a bigger one.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The results</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Every run passed every check: lint, type checks and the existing tests, plus, on the bigger task, a hidden test the agent never saw. A separate AI judge scored each result without knowing which copy it came from (more on that below).</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Small task: tile all open windows</strong> (score out of 19)</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>Branch</th><th>Score</th><th>Tokens</th><th>Cost</th></tr></thead><tbody><tr><td>With comments</td><td>18.3</td><td>2.18M</td><td>$1.42</td></tr><tr><td>Without</td><td>19.0</td><td>1.71M</td><td>$1.04</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Bigger task: keep a window on top</strong> (score out of 23)</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>Branch</th><th>Score</th><th>Tokens</th><th>Cost</th></tr></thead><tbody><tr><td>With comments</td><td>21.7</td><td>9.06M</td><td>$3.84</td></tr><tr><td>Without</td><td>22.0</td><td>9.12M</td><td>$3.95</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The numbers are averages of three runs. The score differences are within noise, and so is the cost on the bigger task. On the small task, the agent used about 22% fewer tokens without comments, which makes sense: there was simply less to read.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The bigger task had a trap. The pinned state has to survive a page reload, and the PHP function that saves the window session drops any key it doesn&#8217;t know. Miss it and the feature looks fine until you reload. That&#8217;s exactly the kind of thing you&#8217;d expect a comment to help with. All six runs found it, with and without comments.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why one run is not enough</h2>\n\n\n\n<p class=\"wp-block-paragraph\">My first plan was to run each branch once. I&#8217;m glad I didn&#8217;t.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On the bigger task, the three runs with comments used 8.21M, 8.79M and 10.17M tokens. The three runs without comments used 7.01M, 9.70M and 10.64M.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If I had picked one run from each branch, I could have written two opposite blog posts. Comparing 10.64M with 8.21M, removing comments makes the agent 30% more expensive. Comparing 7.01M with 10.17M, it makes the agent 31% cheaper. Same task, same code, same day.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Agents are not deterministic. If you&#8217;re measuring one, run it more than once.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How I ran it</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>The agent:</strong> Claude Code with Opus 5.5 at high effort. Same model and settings for every run.</li>\n\n\n\n<li><strong>The two codebases:</strong> our main branch, and a copy with the comments removed. I compiled both and checked that the resulting code is identical. The only comments left are the ones the tools need to work, such as lint directives and plugin headers, about 800 lines.</li>\n\n\n\n<li><strong>The tasks:</strong> two real features, with the same prompt on both branches.</li>\n\n\n\n<li><strong>The checks:</strong> the project&#8217;s own lint, type checks and tests. On the bigger task, also a hidden test I added after the agent finished, so it couldn&#8217;t write code just to pass it.</li>\n\n\n\n<li><strong>The judge:</strong> a separate Claude session read each change and scored it against a checklist written before the runs: does it work, does it follow the project&#8217;s conventions, does it have tests, and so on. The changes were labelled with random names, so the judge didn&#8217;t know which branch each one came from.</li>\n\n\n\n<li><strong>The runs:</strong> three per branch per task, alternating branches so that time of day affected both equally.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">My conclusion</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For the agent, code comments don&#8217;t make a difference to the quality of the code it writes. They don&#8217;t help, and they don&#8217;t hurt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So keep a comment or delete it based on what it does for the people reading the code, not for the agent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This doesn&#8217;t prove comments have zero effect. I tested one model, two tasks and three runs per branch, which is enough to rule out a big effect, not a small one.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Next:</strong> comments made no difference, but removing our <code>docs/</code> folder and AGENTS.md did. That&#8217;s the next post.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Appendix: data and links</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>The <a href=\"https://github.com/WordPress/openstation/tree/28038e9f9d99b74b8b279a858c4ff8826b8ec48d\">codebase with comments</a></li>\n\n\n\n<li>The <a href=\"https://github.com/WordPress/openstation/tree/09f2b460203196654cbd930835cd70856bb52443\">codebase without comments</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/openstation/compare/28038e9f...09f2b460\">Exactly what was removed</a> (GitHub may only show part of it)</li>\n\n\n\n<li>Two of the small-task runs as pull requests: <a href=\"https://github.com/WordPress/openstation/pull/974\">with comments, PR 974</a> and <a href=\"https://github.com/WordPress/openstation/pull/975\">without comments, PR 975</a></li>\n\n\n\n<li>Full results, all runs: <a href=\"https://claude.ai/artifact/YUTg68tcXcf6XCo94g1Uhs\">results page</a></li>\n\n\n\n<li>If you want to see the experiment script and the rubrics, <a href=\"https://epeicher.github.io/wairehouse/openstation/experiments/comments-ab.html\">they are all here</a></li>\n\n\n\n<li>Lines of code, measured with <code>scc</code>:</li>\n</ul>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th></th><th>With</th><th>Without</th></tr></thead><tbody><tr><td>Whole repository</td><td>765,491</td><td>597,332</td></tr><tr><td>Plugin source code</td><td>408,527</td><td>280,421</td></tr></tbody></table><figcaption class=\"wp-element-caption\"><sub>Plugin source code means the code that ships in the plugin (src/, includes/, apps/ and the CSS), without tests, docs, or tooling.</sub></figcaption></figure>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 13 Oct 2026 17:58:37 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Roberto Aranda\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:18;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:27:\"Matt: Neal Stephenson Live!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155205\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"https://ma.tt/2026/10/neal-stephenson-live/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1718:\"<p class=\"wp-block-paragraph\">Speaking of sci-fi authors, <a href=\"https://automattic.com/\">Automattic</a> is hosting Neal Stephenson for a livestream about <a href=\"https://amzn.to/47jviKj\">his new book soon</a>, please tune in!</p>\n\n\n\n<figure class=\"wp-block-embed alignwide is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Neal was a big influence on WordPress! I got hip to him from <a href=\"https://tantek.com/\">Tantek</a>. In the source code of billions of pages you&#8217;ll see this:</p>\n\n\n\n<pre class=\"wp-block-code\"><code>&lt;link rel=\"profile\" href=\"https://gmpg.org/xfn/11\"></code></pre>\n\n\n\n<p class=\"wp-block-paragraph\">GMPG is the <a href=\"https://en.wikipedia.org/wiki/Global_Multimedia_Protocols_Group\">Global Media Protocols Group</a>, &#8220;an <a href=\"https://gmpg.org/\">experiment in Metamemetics</a>.&#8221; Inspired, of course, by the Global Multimedia Protocol Group that owned the virtual real estate in <a href=\"https://en.wikipedia.org/wiki/Snow_Crash\">Snow Crash&#8217;s metaverse</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://meyerweb.com/\">Eric</a>, Tantek, and I were reacting to the idea that there should be a separate heavily-marked-up RDF or XML web, and that HTML couldn&#8217;t be extended or enriched with metadata in a way that was beautiful to both humans and machines. It was really an aesthetic war. (It later got more built out in <a href=\"https://microformats.org/\">Microformats</a>.)</p>\n\n\n\n<p class=\"wp-block-paragraph\">We should revisit some of those principles because the web could use more distribution right now.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 13 Oct 2026 15:53:19 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:19;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"Open Channels FM: Balancing AI Efficiency Costs and Value in Markdown Data and Open Source Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563520\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:106:\"https://openchannels.fm/balancing-ai-efficiency-costs-and-value-in-markdown-data-and-open-source-security/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:150:\"In today\'s news, markdown streamlines AI input, AI-generated security reports increase workloads, and autonomous agent costs affect project efficiency\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 13 Oct 2026 14:15:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:20;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Open Channels FM: Open Channels FM Heading to the Web Summit 2026 in Lisboa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563477\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://openchannels.fm/open-channels-fm-heading-to-the-web-summit-2026-in-lisboa/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:330:\"Next month in November, I&#8217;ll (Bob) be attending the Web Summit in Lisbon, Portugal. I have been to conferences in the past that have had attendance up to 15,000, but never one that has over 70,000 attendees. That&#8217;s a lot of people. A few months ago I applied for media creditation, unsure of their parameters [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 13 Oct 2026 10:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"Bob\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:21;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Matt: Board Agent\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155203\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://ma.tt/2026/10/board-agent/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1830:\"<p class=\"wp-block-paragraph\"><a href=\"https://automattic.com/\">Automattic</a> is always 5–15 years ahead of other companies, but things happen faster now. I predict other companies will start scrambling to add great writers to their boards, because, well, look at the headlines in AI. <a href=\"https://ir.united.com/corporate-governance/board-of-directors\">United&#8217;s board already has Walter Isaacson</a>. Authors are awesome, akin to founders in the startup/tech ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Public offer to all the great sci-fi/etc writers out there who I&#8217;m a huge fan of (<a href=\"https://kenliu.name/\">Ken Liu</a>, <a href=\"https://www.nealstephenson.com/\">Neal Stephenson</a>, <a href=\"https://en.wikipedia.org/wiki/Ted_Chiang\">Ted Chiang</a>, <a href=\"https://andyweirauthor.com/\">Andy Weir</a>, <a href=\"https://www.rameznaam.com/\">Ramez Naam</a>, <a href=\"https://en.wikipedia.org/wiki/Kim_Stanley_Robinson\">Kim Stanley Robinson</a>&#8230;) but not as close to as <a href=\"https://hughhowey.com/\">Hugh</a> (I was part of him meeting his wife, officiated one of their weddings), I offer my services as your Board Agent to negotiate compensation and contracts for you! 1% fee, donated to the <a href=\"https://wordpressfoundation.org/\">WordPress Foundation</a> or <a href=\"https://locusmag.com/\">Locus Magazine</a>. I&#8217;ve become a bit of an expert in board protections, dynamics, compensation, and such. <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Aside:</em> If you haven&#8217;t seen the <a href=\"https://en.wikipedia.org/wiki/Turn_Every_Page\">Robert Caro / Robert Gottlieb documentary Turn Every Page</a>, run, don&#8217;t walk to your nearest streaming service!</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 13 Oct 2026 09:10:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:22;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"OpenStation Blog: What WordPress would have looked like in 1995\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1457\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://openstation.blog/2026/10/12/what-wordpress-would-have-looked-like-in-1995/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3391:\"<p class=\"wp-block-paragraph\">I&#8217;ve been wondering how far a theme can take <a href=\"https://wordpress.org/plugins/desktop-mode/\">OpenStation</a>. Not just a wallpaper and a different color, but everything: windows, dock, menus, fonts, icons, layouts, etc. So I tried to make wp-admin look like two operating systems from a long time ago.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"The same wp-admin desktop, with the same windows open, switching between a 1995 look (teal desk, grey windows, a taskbar) and a 1984 look in black and white.\" class=\"wp-image-1454\" height=\"750\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/10/openstation-retro-95-to-84.gif?resize=1200%2C750&#038;ssl=1\" width=\"1200\" /><figcaption class=\"wp-element-caption\">Can you believe that this is still WordPress? Turns out that the web is still fun! You only need WordPress, OpenStation, and one of these two themes.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/mmtr/wp-os-retro-95\"><strong>Retro 95</strong></a> reimagines wp-admin as Windows 95. It even comes with a Start menu! And the classic clock sitting in the bottom-right corner is also there. You can <a href=\"https://wp-os-retro-95.space.fast/\">try it live</a>.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"wp-admin with the Retro 95 theme: opening Posts from the Start menu and writing a new post titled Hello from 1995.\" class=\"wp-image-1455\" height=\"540\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/10/openstation-retro-95.gif?resize=960%2C540&#038;ssl=1\" width=\"960\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/mmtr/wp-os-retro-84\"><strong>Retro 84</strong></a> is the counterpart for Apple fans. It turns wp-admin into the first graphical OS that many people ever saw: the original Macintosh&#8217;s System 1. The beloved monochrome display, the classic pixelated font, and more! Check out the <a href=\"https://wp-os-retro-84.space.fast/\">live demo</a>. </p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"wp-admin with the Retro 84 theme in black and white: previewing documents on the desk and writing a new post titled Hello from 1984.\" class=\"wp-image-1456\" height=\"540\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/10/openstation-retro-84.gif?resize=960%2C540&#038;ssl=1\" width=\"960\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">And here&#8217;s a fun fact: every icon is pixel art typed into a text file, one character per pixel. The fonts were also made the same way, letter by letter.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"For each theme, a text file where every character is one pixel, the icon it becomes (a 1995 computer and a 1984 floppy disk), and the rest of the theme\'s icons.\" class=\"wp-image-1462\" height=\"717\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/10/openstation-retro-icons-as-text.png?resize=1024%2C717&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Underneath, it&#8217;s the same wp-admin as always, just a few decades older.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you want to build your own theme, <a href=\"https://github.com/WordPress/openstation/blob/trunk/docs/desktop-themes.md\">the docs</a> list everything a theme can change. Maybe it&#8217;s time for a proper Windows Vista comeback.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 12 Oct 2026 11:31:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Miguel Torres\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"Open Channels FM: Building Stability Through Diversification in Tech Careers\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563193\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://openchannels.fm/building-stability-through-diversification-in-tech-careers/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:221:\"In a fast-evolving tech industry, professionals are embracing diversification for stability and growth. This strategy fosters financial security, creativity, and adaptability, preparing individuals for unforeseen changes.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 12 Oct 2026 09:18:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"Open Channels FM: OCN Week in Review #5: Scale, Adaptation, Verification and Infrastructure\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563443\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"https://openchannels.fm/ocn-week-in-review-5-scale-adaptation-verification-and-infrastructure/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:287:\"This week on Open Channels News, discover how AI is changing hardware, security reports, and gaming, plus the latest WordPress and enterprise data updates. Explore our concise wrap-up of major open source and tech stories, along with the recurring themes shaping the industry’s future.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 09 Oct 20